import{a6 as we,N as se,E as y,R as Ae,P as We,g as Ee,h as Ve,i as Be,L as je,a7 as Ie,K as Ge,J as Ye,H as He,G as Qe,F as Xe,D as Ze,B as Ke,z as Je,y as et,w as tt,x as at,v as nt,q as it,o as rt,l as st,f as a,t as ot,O as lt,a9 as B,ad as ct,ae as dt,n as ut,I as mt,a8 as ve,r as me,a4 as pt,a3 as pe,a2 as gt,$ as _e,_ as ht,Y as ft,X as bt,W as Fe,U as Ce,T as De,S as yt,a1 as wt,a0 as vt,Z as St}from"./visuals-BRiTwSMI.js";const n=i=>String.raw`\htmlClass{fm-var}{${i}}`,t=(i,l=2)=>a(i,l).replace(/,/g,"{,}"),e=(i,l=2)=>a(i,l),Se={"2.1":7,"2.2":7,"2.3.1":7,"2.3":8,"2.4":8,3:8,"4.1":8,"4.2":9,5:9},c=i=>{const l=Object.keys(Se).sort((N,Ne)=>Ne.length-N.length).find(N=>i.startsWith(N))??"3";return{doc:"syllabus",pages:`p. ${Se[l]}`,pdfPage:Se[l],note:`Topic ${i} — listed in the official syllabus`}},xt={"book-101-200":97,"book-201-300":197,"book-301-400":297,"book-401-500":397,"book-501-600":497},r=(i,l,N)=>({doc:i,pages:`p. ${l}`,pdfPage:l-xt[i],note:N}),R=[6,8,7,9,12,7,5],O=y(R),Me=We(R),W=se(R),ge=se(R,!1),T=lt(R),D=6/4,oe=1-B(D),L=Ee(55,53,.25),P=Ve(55,53,54.3,.25),Y=Be(55,53,54.3,.32),$t=Ee(55,53,.32),d=je(.08,.06,.4,2),w=Ie(6210),he=Ge(12,36),g=Ye(45,10,20),H=He(8,2),le=Qe(4.6,4,1.2,16),v=we(38.2,4.1,12,34.5,6.3,10),kt=we(38.2,4.1,12,34.5,6.3,10,!0),j=[32,28,35,30,33,29,31,34],G=[29,27,31,28,30,28,29,30],h=Xe(j,G),Rt=[[23,25,21,24,22],[28,27,30,26,29],[22,24,23,25,21]],m=Ze(Rt),qe=ct(.95,2,12),Tt=[[30,20,10],[20,25,35]],b=Ke(Tt),Oe=dt(.95,2),U=Je(171,200,.9),z=[2,4,5,7,8,10],k=[11,16,19,23,28,33],M=et(z,k),s=tt(z,k),ce=z.reduce((i,l)=>i+(l-y(z))**2,0),de=z.reduce((i,l,N)=>i+(l-y(z))*(k[N]-y(k)),0),Pt=[[10,12,11,13,9],[11,11,12,10,13],[12,14,10,11,12]],u=at(Pt),_t=[10,12,11,14,13],S=nt(_t),Q=ot([4,6,5,5],[100,100,100,100]),X=it([4,6,5,5],100),_=rt([12,8,10],[4,4,2]),A=Ae(8,5,6),fe=Ae(8,2,3),xe=st(15e4,1e5),be=ut(.08,[-1e5,45e3,45e3,45e3]),Z="Standard normal (Z) table",K="t table (critical values by df)",Ct="Chi-square table",Le="F table (α = 0.05)",ye="Control chart constants (A₂, D₃, D₄, d₂)",$e="Statistics mode, if your calculator has one: use the SAMPLE SD key (often sx or σn−1), not σx/σn.",Dt="Store intermediate results in memory (M+ / MR) instead of re-typing rounded values.",Mt="Type the whole radicand first, then press √ — e.g. ( a ÷ b ) √.",qt=[{id:"rpn",name:"Risk Priority Number (RPN)",short:"Severity × Occurrence × Detection — ranks FMEA failure modes.",group:"measure",phase:2,syllabusRef:"2.1.4",supplementary:!1,definition:"In a Failure Modes & Effects Analysis each failure mode is rated 1–10 for **Severity** of the effect, **Occurrence** (how often the cause happens) and **Detection** (how unlikely current controls are to catch it — 10 = almost impossible to detect). The RPN multiplies the three ratings to prioritise action.",tex:String.raw`\text{RPN} = ${n("S")} \times ${n("O")} \times ${n("D")}`,variables:[{symbol:"S",meaning:"Severity of the effect on the customer",unit:"rating 1–10"},{symbol:"O",meaning:"Occurrence (likelihood) of the cause",unit:"rating 1–10"},{symbol:"D",meaning:"Detection — 10 means the control is almost certain to MISS it",unit:"rating 1–10"}],whenToUse:["Prioritising failure modes in an FMEA during Measure.","Re-scoring after an action to show the risk reduction.","Comparing modes — but always review very high severity on its own, whatever the RPN."],units:'A unit-free score from 1 to 1,000. It is an ordinal ranking aid, not a probability — an RPN of 200 is not "twice as risky" as 100.',example:{title:"SIM-swap fraud control",scenario:'Failure mode: "SIM swap processed without ID check". Severity **8** (fraud loss), Occurrence **5**, Detection **6**. After adding a mandatory OTP step, Occurrence falls to **2** and Detection to **3**.',values:[{symbol:"S",value:"8",meaning:"severity"},{symbol:"O",value:"5",meaning:"occurrence"},{symbol:"D",value:"6",meaning:"detection"}],substituted:String.raw`\text{RPN} = 8 \times 5 \times 6`,steps:[{tex:String.raw`8 \times 5 = 40`,note:"Severity × occurrence."},{tex:String.raw`40 \times 6 = ${A}`,note:"× detection."},{tex:String.raw`\text{After: } 8 \times 2 \times 3 = ${fe}`,note:"Re-score after the action."}],result:A,answer:`RPN = ${A} → ${fe} after the action (${e((A-fe)/A*100,0)}% reduction)`},solution:["Rate S, O and D on the team's agreed 1–10 scales.",`Multiply: 8 × 5 × 6 = **${A}**.`,`After the action: 8 × 2 × 3 = **${fe}** — severity rarely changes; actions reduce O or D.`],trap:{title:"Detection runs backwards",body:"A **high** detection rating means the failure is **hard** to detect. Students often give a well-detected failure a high D. Also: two modes can share an RPN while one has severity 10 — review severity separately."},incorrect:{calculation:String.raw`8 + 5 + 6 = 19`,result:"19",whyWrong:"RPN multiplies the ratings; adding them hides the interaction between likelihood and detectability.",correct:String.raw`8 \times 5 \times 6 = ${A}`,correctResult:`${A}`},denominatorErrors:['Rating detection as "how likely we are to detect it" (inverted scale).',"Expecting an action to lower severity — usually only O and D change.","Treating RPN differences as ratios of risk."],related:["mean","cbr"],examTools:{tables:["No table needed — the FMEA rating scales are given in the question"],keys:["Simple multiplication: S × O × D =.","For percentage reduction: (before − after) ÷ before × 100."]},sources:[c("2.1.4"),r("book-101-200",123,"FMEA worksheet and RPN"),r("book-101-200",134,"Detection ranking criteria (10 = almost impossible to detect)")]},{id:"mean",name:"Arithmetic Mean",short:"The balance point of the data: sum ÷ count.",group:"measure",phase:2,syllabusRef:"2.2.2",supplementary:!1,definition:"The **mean** is the sum of the values divided by how many there are. The sample mean x̄ estimates the population mean μ. It uses every value, so it is pulled towards outliers and long tails — compare it with the median.",tex:String.raw`\bar{x} = \dfrac{${n(String.raw`\sum x_i`)}}{${n("n")}}`,altTex:[{label:"Weighted (frequency table)",tex:String.raw`\bar{x} = \dfrac{\sum f_i x_i}{\sum f_i}`}],variables:[{symbol:String.raw`\sum x_i`,meaning:"Sum of all observations",unit:"data units"},{symbol:"n",meaning:"Number of observations",unit:"count"}],whenToUse:["Describing the centre of continuous data (handle time, MTTR, latency).","Feeding standard deviation, capability and hypothesis tests.","Combining groups: weight each mean by its size."],units:"Same units as the data (minutes, hours, ms).",example:{title:"Average handle time",scenario:`Seven calls had handle times of **${R.join(", ")} minutes**.`,values:[{symbol:String.raw`\sum x_i`,value:`${R.reduce((i,l)=>i+l,0)}`,meaning:"total minutes"},{symbol:"n",value:`${R.length}`,meaning:"calls"}],substituted:String.raw`\bar{x} = \dfrac{${R.join("+")}}{7}`,steps:[{tex:String.raw`\sum x_i = ${R.reduce((i,l)=>i+l,0)}`,note:"Add every value."},{tex:String.raw`\bar{x} = \dfrac{54}{7} = ${t(O,3)}`,note:"Divide by n."}],result:O,answer:`x̄ = ${e(O,2)} min (median ${e(Me,0)} min)`},solution:["Sum the values: 54 minutes.",`Divide by n = 7: x̄ = **${e(O,2)} min**.`,`The median is ${Me} min — the 12-minute call pulls the mean above it (right skew).`],trap:{title:"Mean of means",body:"When groups have different sizes, the overall mean is **not** the average of the group means. Rebuild each total (n × mean), add, then divide by the total n."},incorrect:{calculation:String.raw`\dfrac{54}{6} = 9`,result:"9 min",whyWrong:"Divided by n − 1. The n − 1 correction belongs in the sample variance, not the mean.",correct:String.raw`\dfrac{54}{7} = ${t(O,2)}`,correctResult:`${e(O,2)} min`},denominatorErrors:["Dividing by n − 1 instead of n.","Averaging group means with unequal group sizes.","Dividing a frequency table by the number of rows instead of Σf."],related:["stdev","stderr","zscore"],examTools:{tables:["No table needed"],keys:["Add with the memory key: value M+ for each, then MR ÷ n.","If your calculator has a statistics mode, its x̄ key gives the mean directly — use it to check."]},sources:[c("2.2.2"),r("book-101-200",140,"Measures of central tendency — mean, median, mode")]},{id:"stdev",name:"Standard Deviation",short:"Typical distance of the data from its mean — sample uses n − 1.",group:"measure",phase:2,syllabusRef:"2.2.2",supplementary:!1,definition:"The standard deviation measures spread. Square each deviation from the mean, add them, divide by **n − 1** for a sample (s) or **N** for a whole population (σ), then take the square root. Sample data almost always use n − 1, because x̄ is itself estimated from the data.",tex:String.raw`s = \sqrt{\dfrac{${n(String.raw`\sum (x_i - \bar{x})^2`)}}{${n("n - 1")}}}`,altTex:[{label:"Population",tex:String.raw`\sigma = \sqrt{\dfrac{\sum (x_i - \mu)^2}{N}}`},{label:"Computational form",tex:String.raw`s = \sqrt{\dfrac{\sum x^2 - (\sum x)^2/n}{n-1}}`}],variables:[{symbol:String.raw`\sum (x_i - \bar{x})^2`,meaning:"Sum of squared deviations (SS)",unit:"units²"},{symbol:"n - 1",meaning:"Degrees of freedom for a sample",unit:"count"}],whenToUse:["Describing variation in continuous data.","Estimating σ for capability, z-scores, confidence intervals and tests.","Combining independent sources: add variances, then take the root."],units:"Same units as the data. The **variance** (s²) is in squared units.",example:{title:"Handle-time spread",scenario:`Same seven calls: **${R.join(", ")} min**, x̄ = ${e(O,3)}.`,values:[{symbol:String.raw`\sum (x_i - \bar{x})^2`,value:e(T*6,3),meaning:"sum of squares"},{symbol:"n - 1",value:"6",meaning:"degrees of freedom"}],substituted:String.raw`s = \sqrt{\dfrac{${t(T*6,3)}}{6}}`,steps:[{tex:String.raw`s^2 = ${t(T*6,3)} \div 6 = ${t(T,3)}`,note:"Variance."},{tex:String.raw`s = \sqrt{${t(T,3)}} = ${t(W,3)}`,note:"Square root."}],result:W,answer:`s = ${e(W,2)} min (population formula would give ${e(ge,2)})`},solution:[`Deviations from ${e(O,3)}, squared and summed: SS = ${e(T*6,3)}.`,`Divide by n − 1 = 6: s² = ${e(T,3)}.`,`s = √${e(T,3)} = **${e(W,2)} min**.`],trap:{title:"Sample (n − 1) vs population (n)",body:`Dividing by n gives ${e(ge,2)} instead of ${e(W,2)} — always too small for a sample. Use N only when the data are the **entire** population (e.g. every month of a closed contract year).`},incorrect:{calculation:String.raw`\sqrt{${t(T*6,3)} \div 7} = ${t(ge,2)}`,result:e(ge,2),whyWrong:"Population formula applied to a sample — it underestimates the process spread.",correct:String.raw`\sqrt{${t(T*6,3)} \div 6} = ${t(W,2)}`,correctResult:e(W,2)},denominatorErrors:["n instead of n − 1 for sample data.","Forgetting the square root (reporting the variance).","Adding standard deviations of independent stages — add variances instead."],related:["mean","zscore","stderr","cp"],examTools:{tables:["No table needed"],keys:[$e,Dt,"By hand: build a column of (x − x̄)², sum it, ÷ (n − 1), then √."]},sources:[c("2.2.2"),r("book-101-200",141,"Population vs sample notation"),r("book-101-200",151,"Variance and standard deviation")]},{id:"zscore",name:"Z-score & Normal Probability",short:"How many standard deviations a value is from the mean.",group:"measure",phase:2,syllabusRef:"2.2.3",supplementary:!1,definition:"A z-score standardises a value: **z = (x − μ)/σ**. For normally distributed data the Z table then gives the probability below that value, Φ(z). Areas beyond a limit, between limits, and percentile values all come from this one conversion.",tex:String.raw`z = \dfrac{${n("x")} - ${n(String.raw`\mu`)}}{${n(String.raw`\sigma`)}}`,altTex:[{label:"Proportion above x",tex:String.raw`P(X > x) = 1 - \Phi(z)`},{label:"Value at a percentile",tex:String.raw`x = \mu + z_p\,\sigma`}],variables:[{symbol:"x",meaning:"The value of interest (e.g. an SLA threshold)",unit:"data units"},{symbol:String.raw`\mu`,meaning:"Process mean",unit:"data units"},{symbol:String.raw`\sigma`,meaning:"Process standard deviation",unit:"data units"}],whenToUse:["Estimating the share of output beyond a specification or SLA threshold.","Setting a target that a given percentage of cases will meet.","For a sample MEAN, replace σ with σ/√n."],units:"z has no units (number of standard deviations). Probabilities are fractions or percentages.",example:{title:"Latency above the SLA",scenario:"Backbone latency is normal with **μ = 30 ms**, **σ = 4 ms**. The SLA threshold is **36 ms**. What share of measurements breach it?",values:[{symbol:"x",value:"36",meaning:"threshold (ms)"},{symbol:String.raw`\mu`,value:"30",meaning:"mean (ms)"},{symbol:String.raw`\sigma`,value:"4",meaning:"SD (ms)"}],substituted:String.raw`z = \dfrac{36 - 30}{4}`,steps:[{tex:String.raw`z = ${t(D,2)}`,note:"Standardise."},{tex:String.raw`\Phi(1.50) = ${t(B(D),4)}`,note:"Z table: area to the left."},{tex:String.raw`1 - ${t(B(D),4)} = ${t(oe,4)}`,note:"Area to the right."}],result:D,answer:`z = ${e(D,2)} → ${e(oe*100,2)}% of measurements exceed 36 ms`},solution:["z = (36 − 30) ÷ 4 = **1.50**.",`Z table: Φ(1.50) = ${e(B(D),4)} lie below 36 ms.`,`Above: 1 − ${e(B(D),4)} = **${e(oe*100,2)}%**.`],trap:{title:"Individuals vs averages",body:"If the question is about the **average** of n items, its spread is σ/√n, so z = (x̄ − μ)/(σ/√n). Using σ makes the tail far too large."},incorrect:{calculation:String.raw`P = \Phi(1.5) = ${t(B(D),4)}`,result:e(B(D)*100,2)+"%",whyWrong:"The table gives the area to the LEFT. The breach share is to the right of the threshold.",correct:String.raw`P = 1 - \Phi(1.5) = ${t(oe,4)}`,correctResult:e(oe*100,2)+"%"},denominatorErrors:["Dividing by the variance σ² instead of σ.","Using σ for a sample mean (should be σ/√n).","Two-sided z (1.96) for a one-sided target."],related:["stdev","cpk","sigmaLevel","stderr"],examTools:{tables:[Z],keys:["Round z to 2 decimals to read the table (row = first decimal, column = second).",'For "above", subtract the table value from 1; for "between", subtract the two table values.']},sources:[c("2.2.3"),r("book-101-200",152,"The normal curve"),r("book-101-200",153,"Z-scores and the standard normal distribution")]},{id:"cp",name:"Process Capability Cp",short:"Tolerance width ÷ 6σ_within — potential, if centred.",group:"measure",phase:2,syllabusRef:"2.4.1",supplementary:!1,definition:"Cp compares the width of the specification with the natural short-term spread of a **stable** process (6σ_within). It ignores where the mean sits, so it shows what the process **could** achieve if perfectly centred (entitlement). σ_within is estimated from R̄/d₂, S̄/c₄ or MR̄/1.128.",tex:String.raw`C_p = \dfrac{${n(String.raw`\text{USL}`)} - ${n(String.raw`\text{LSL}`)}}{6\,${n(String.raw`\sigma_{\text{within}}`)}}`,altTex:[{label:"σ_within from an Xbar-R chart",tex:String.raw`\hat{\sigma}_{\text{within}} = \overline{R} / d_2`}],variables:[{symbol:String.raw`\text{USL}, \text{LSL}`,meaning:"Upper / lower specification limits (voice of the customer)",unit:"data units"},{symbol:String.raw`\sigma_{\text{within}}`,meaning:"Short-term (within-subgroup) standard deviation",unit:"data units"}],whenToUse:["Two-sided specification on continuous, normal, stable data.","Showing the potential capability before centring the process.","Compare with Cpk: a big gap means the mean is off-centre."],units:"Unit-free ratio. 1.00 = spread exactly fills the tolerance; 1.33 is a common minimum; 2.0 ≈ Six Sigma short-term.",example:{title:"Rectifier output voltage",scenario:"Cell-site DC rectifiers must output **53–55 V**. An Xbar-R chart is stable with σ_within = **0.25 V**.",values:[{symbol:String.raw`\text{USL}`,value:"55",meaning:"V"},{symbol:String.raw`\text{LSL}`,value:"53",meaning:"V"},{symbol:String.raw`\sigma_{\text{within}}`,value:"0.25",meaning:"V"}],substituted:String.raw`C_p = \dfrac{55 - 53}{6 \times 0.25}`,steps:[{tex:String.raw`55 - 53 = 2`,note:"Tolerance width."},{tex:String.raw`6 \times 0.25 = 1.5`,note:"Process spread."},{tex:String.raw`C_p = 2 \div 1.5 = ${t(L,2)}`,note:"Ratio."}],result:L,answer:`Cp = ${e(L,2)}`},solution:["Tolerance = 55 − 53 = 2 V.","6σ = 6 × 0.25 = 1.5 V.",`Cp = 2 ÷ 1.5 = **${e(L,2)}** — capable if centred.`],trap:{title:"Within vs overall σ",body:"Cp and Cpk use the **within** (short-term) σ. Using the overall (long-term) standard deviation gives **Pp**. Exam outputs often list both — pick deliberately."},incorrect:{calculation:String.raw`\dfrac{2}{3 \times 0.25} = ${t(2/.75,2)}`,result:e(2/.75,2),whyWrong:"Divided by 3σ. Cp compares the FULL tolerance with the FULL ±3σ spread (6σ).",correct:String.raw`\dfrac{2}{6 \times 0.25} = ${t(L,2)}`,correctResult:e(L,2)},denominatorErrors:["3σ instead of 6σ.","Using R̄ or MR̄ directly as σ (divide by d₂ / 1.128 first).","Overall σ (that is Pp)."],related:["cpk","ppk","sigmaLevel","xbarR"],examTools:{tables:[ye+" — for d₂ when σ comes from R̄"],keys:["Compute the denominator first: 6 × σ = M+, then (USL − LSL) ÷ MR.","Keep σ unrounded (R̄ ÷ d₂ in memory)."]},sources:[c("2.4.1"),r("book-201-300",216,"Capability formulas: Cp/Pp (potential) vs Cpk/Ppk (actual)"),r("book-201-300",221,"Capability assumes normal data — test normality first")]},{id:"cpk",name:"Process Capability Cpk",short:"Distance to the NEAREST spec ÷ 3σ_within — actual short-term capability.",group:"measure",phase:2,syllabusRef:"2.4.1",supplementary:!1,definition:"Cpk accounts for centring: it measures how many 3σ_within fit between the mean and the **nearer** specification limit. Cpk ≤ Cp always; they are equal only when the process is perfectly centred. With a one-sided spec, Cpk is just Cpu or Cpl.",tex:String.raw`C_{pk} = \min\!\left(\dfrac{${n(String.raw`\text{USL}`)} - ${n(String.raw`\bar{x}`)}}{3${n(String.raw`\sigma_w`)}},\ \dfrac{${n(String.raw`\bar{x}`)} - ${n(String.raw`\text{LSL}`)}}{3${n(String.raw`\sigma_w`)}}\right)`,variables:[{symbol:String.raw`\bar{x}`,meaning:"Process mean",unit:"data units"},{symbol:String.raw`\text{USL}, \text{LSL}`,meaning:"Specification limits",unit:"data units"},{symbol:String.raw`\sigma_w`,meaning:"Within (short-term) standard deviation",unit:"data units"}],whenToUse:["Real short-term capability of a stable process, including centring.","One-sided specs (SLA maximum, minimum speed): use just the relevant side.","Compare with Ppk to see how much long-term drift costs you."],units:"Unit-free. Negative if the mean is outside a specification limit.",example:{title:"Off-centre rectifiers",scenario:"Same rectifiers (53–55 V, σ_within = 0.25 V), but the mean has drifted to **54.3 V**.",values:[{symbol:String.raw`\bar{x}`,value:"54.3",meaning:"V"},{symbol:String.raw`\text{USL}`,value:"55",meaning:"V"},{symbol:String.raw`\text{LSL}`,value:"53",meaning:"V"},{symbol:String.raw`\sigma_w`,value:"0.25",meaning:"V"}],substituted:String.raw`C_{pk} = \min\!\left(\dfrac{55 - 54.3}{0.75},\ \dfrac{54.3 - 53}{0.75}\right)`,steps:[{tex:String.raw`C_{pu} = 0.7 \div 0.75 = ${t(.7/.75,3)}`,note:"Upper side."},{tex:String.raw`C_{pl} = 1.3 \div 0.75 = ${t(1.3/.75,3)}`,note:"Lower side."},{tex:String.raw`C_{pk} = ${t(P,2)}`,note:"Take the minimum."}],result:P,answer:`Cpk = ${e(P,2)} (Cp is still ${e(L,2)})`},solution:["Distance to USL = 0.7 V; to LSL = 1.3 V.","3σ = 0.75 V.",`Cpk = min(0.933, 1.733) = **${e(P,2)}** — centring would raise it to ${e(L,2)}.`],trap:{title:"Forgetting min()",body:"Cpk is set by the **worse** side. Reporting the larger ratio (or an average of the two sides) overstates capability."},incorrect:{calculation:String.raw`\dfrac{54.3 - 53}{0.75} = ${t(1.3/.75,2)}`,result:e(1.3/.75,2),whyWrong:"Used the farther limit. The defects come from the side nearer the mean.",correct:String.raw`\dfrac{55 - 54.3}{0.75} = ${t(P,2)}`,correctResult:e(P,2)},denominatorErrors:["6σ instead of 3σ (each side is a half-width).","Overall σ (that is Ppk).","Inventing a lower limit of 0 for a one-sided SLA."],related:["cp","ppk","zscore","sigmaLevel"],examTools:{tables:[ye+" — if σ must come from R̄/d₂ or MR̄/1.128"],keys:["Compute both sides, then keep the smaller.","Store 3σ in memory and divide each distance by MR."]},sources:[c("2.4.1"),r("book-201-300",216,"Cpk — reality of short-term capability relative to specs"),r("book-201-300",218,"Capability indices and centring")]},{id:"ppk",name:"Process Performance Ppk",short:"Like Cpk but with the overall (long-term) standard deviation.",group:"measure",phase:2,syllabusRef:"2.4.1",supplementary:!1,definition:"Pp and Ppk use the **overall** sample standard deviation of all the data, which includes shifts and drifts between subgroups. Ppk therefore describes what customers actually experienced over the period. Ppk ≤ Cpk for most real processes; a big gap signals instability.",tex:String.raw`P_{pk} = \min\!\left(\dfrac{${n(String.raw`\text{USL}`)} - ${n(String.raw`\bar{x}`)}}{3${n("s")}},\ \dfrac{${n(String.raw`\bar{x}`)} - ${n(String.raw`\text{LSL}`)}}{3${n("s")}}\right)`,altTex:[{label:"Pp (ignores centring)",tex:String.raw`P_p = \dfrac{\text{USL} - \text{LSL}}{6s}`}],variables:[{symbol:"s",meaning:"Overall (long-term) sample standard deviation",unit:"data units"},{symbol:String.raw`\bar{x}`,meaning:"Overall mean",unit:"data units"},{symbol:String.raw`\text{USL}, \text{LSL}`,meaning:"Specification limits",unit:"data units"}],whenToUse:["Reporting long-term performance actually delivered.","Converting to long-term PPM: PPM ≈ [1 − Φ(3·Ppk)] × 10⁶ for the worse side.","Comparing with Cpk to quantify between-subgroup drift."],units:"Unit-free.",example:{title:"Rectifiers over a quarter",scenario:"Over three months the rectifier data (53–55 V) have mean **54.3 V** and overall s = **0.32 V** (σ_within = 0.25 V).",values:[{symbol:"s",value:"0.32",meaning:"overall SD (V)"},{symbol:String.raw`\bar{x}`,value:"54.3",meaning:"V"},{symbol:String.raw`\text{USL}`,value:"55",meaning:"V"}],substituted:String.raw`P_{pk} = \dfrac{55 - 54.3}{3 \times 0.32}`,steps:[{tex:String.raw`3s = 0.96`,note:"Long-term half-spread."},{tex:String.raw`P_{pk} = 0.7 \div 0.96 = ${t(Y,3)}`,note:"Nearer limit (USL)."}],result:Y,answer:`Ppk = ${e(Y,2)} (Cpk ${e(P,2)}, Pp ${e($t,2)})`},solution:["Nearer limit is the USL (0.7 V away).","3s = 3 × 0.32 = 0.96 V.",`Ppk = 0.7 ÷ 0.96 = **${e(Y,2)}**; the drop from Cpk (${e(P,2)}) is the cost of drift.`],trap:{title:"C = within, P = overall",body:"Memorise: **C**apability = short-term **within** σ; **P**erformance = long-term **overall** σ. Mixing them is the single most common capability error in exams."},incorrect:{calculation:String.raw`\dfrac{0.7}{3 \times 0.25} = ${t(P,2)}`,result:e(P,2),whyWrong:"Used σ_within — that is Cpk.",correct:String.raw`\dfrac{0.7}{3 \times 0.32} = ${t(Y,2)}`,correctResult:e(Y,2)},denominatorErrors:["Within σ (gives Cpk).","6s instead of 3s.","Population SD (n) for sample data."],related:["cpk","cp","sigmaLevel","stdev"],examTools:{tables:[Z+" — to convert Ppk to PPM (z = 3·Ppk)"],keys:[$e,"Then (nearer distance) ÷ (3 × s)."]},sources:[c("2.4.1"),r("book-201-300",216,"Pp/Ppk use the long-term standard deviation"),r("book-201-300",224,"Capability output: within vs overall")]},{id:"grr",name:"Gage R&R (%Study Var, %Contribution, ndc)",short:"How much of the observed variation is measurement noise.",group:"measure",phase:2,syllabusRef:"2.3.3",supplementary:!1,definition:"Measurement variation (Gage R&R) combines **repeatability** (same appraiser, same part) and **reproducibility** (between appraisers). Components add as **variances**. %Study Variation compares standard deviations; %Contribution compares variances; ndc says how many groups of parts the gage can tell apart.",tex:String.raw`\%\text{SV} = \dfrac{${n(String.raw`\sigma_{\text{GRR}}`)}}{${n(String.raw`\sigma_{\text{total}}`)}} \times 100`,altTex:[{label:"Combine components",tex:String.raw`\sigma_{\text{GRR}}^2 = \sigma_{\text{repeat}}^2 + \sigma_{\text{reprod}}^2,\quad \sigma_{\text{total}}^2 = \sigma_{\text{GRR}}^2 + \sigma_{\text{part}}^2`},{label:"%Contribution",tex:String.raw`\%\text{Contribution} = \dfrac{\sigma_{\text{GRR}}^2}{\sigma_{\text{total}}^2} \times 100`},{label:"%Tolerance and ndc",tex:String.raw`\%\text{Tol} = \dfrac{6\sigma_{\text{GRR}}}{\text{USL} - \text{LSL}} \times 100,\quad \text{ndc} = \left\lfloor 1.41 \dfrac{\sigma_{\text{part}}}{\sigma_{\text{GRR}}} \right\rfloor`}],variables:[{symbol:String.raw`\sigma_{\text{GRR}}`,meaning:"Total gage (measurement system) standard deviation",unit:"data units"},{symbol:String.raw`\sigma_{\text{total}}`,meaning:"Total observed standard deviation (gage + parts)",unit:"data units"}],whenToUse:["Before trusting any Measure-phase data (variable MSA).","AIAG guidance: < 10% acceptable, 10–30% marginal, > 30% unacceptable (%SV or %Tolerance).","ndc ≥ 5 for the gage to support process control."],units:"Percentages; ndc is a whole number (Minitab truncates).",example:{title:"Optical power meter",scenario:"A crossed study gives σ_repeat = **0.08 dB**, σ_reprod = **0.06 dB**, σ_part = **0.40 dB**; tolerance = **2 dB**.",values:[{symbol:String.raw`\sigma_{\text{GRR}}`,value:e(d.sdGrr,3),meaning:"√(0.08² + 0.06²)"},{symbol:String.raw`\sigma_{\text{total}}`,value:e(d.sdTotal,4),meaning:"√(0.1² + 0.4²)"}],substituted:String.raw`\%\text{SV} = \dfrac{0.1}{${t(d.sdTotal,4)}} \times 100`,steps:[{tex:String.raw`\sigma_{\text{GRR}} = \sqrt{0.0064 + 0.0036} = 0.1`,note:"Add variances."},{tex:String.raw`\sigma_{\text{total}} = \sqrt{0.01 + 0.16} = ${t(d.sdTotal,4)}`,note:"Add part variance."},{tex:String.raw`\%\text{SV} = ${t(d.pctStudyVar,1)}\%,\ \%\text{Contr} = ${t(d.pctContribution,2)}\%`,note:"SD ratio vs variance ratio."},{tex:String.raw`\text{ndc} = \lfloor 1.41 \times 4 \rfloor = ${d.ndc}`,note:"Distinct categories."}],result:d.pctStudyVar,answer:`%SV = ${e(d.pctStudyVar,1)}% (marginal), %Contribution = ${e(d.pctContribution,2)}%, %Tolerance = ${e(d.pctTolerance??0,0)}%, ndc = ${d.ndc}`},solution:["Combine repeatability and reproducibility as variances: σ_GRR = 0.10 dB.",`σ_total = √(0.10² + 0.40²) = ${e(d.sdTotal,4)} dB.`,`%SV = **${e(d.pctStudyVar,1)}%** — marginal (10–30%); %Contribution = ${e(d.pctContribution,2)}%; ndc = ${d.ndc} (adequate).`],trap:{title:"%Contribution vs %Study Variation",body:`They answer different questions and give very different numbers (${e(d.pctContribution,1)}% vs ${e(d.pctStudyVar,1)}% here). %Contribution squares the ratio. The 10/30 thresholds apply to %SV and %Tolerance; for %Contribution the usual guide is 1% / 9%.`},incorrect:{calculation:String.raw`\dfrac{0.08 + 0.06}{0.4} \times 100 = 35\%`,result:"35%",whyWrong:"Added the standard deviations and divided by part variation only. Components add as variances, and the denominator is the TOTAL.",correct:String.raw`\dfrac{0.1}{${t(d.sdTotal,4)}} \times 100 = ${t(d.pctStudyVar,1)}\%`,correctResult:`${e(d.pctStudyVar,1)}%`},denominatorErrors:["Dividing by part SD instead of total SD.","Adding SDs instead of variances.","Using 5.15σ (old convention) when the question says 6σ."],related:["stdev","cp"],examTools:{tables:["No statistical table — AIAG thresholds (10% / 30%, ndc ≥ 5) are in the reference material"],keys:["Square, add, then √: (0.08 x² + 0.06 x²) √.","ndc: truncate, do not round."]},sources:[c("2.3.3"),r("book-101-200",185,"Gage R&R output: %Contribution and %Study Variation"),r("book-101-200",186,"Number of distinct categories and AIAG acceptance guidelines")]},{id:"sigmaLevel",name:"Sigma Level (from DPMO)",short:"Long-term DPMO → Z → + 1.5 shift = short-term sigma level.",group:"measure",phase:2,syllabusRef:"2.4.3",supplementary:!1,definition:"The sigma level expresses defect performance on the z scale. Convert long-term DPMO to a probability, read Z_LT from the normal table, then add the conventional **1.5σ shift** to report the short-term sigma level. 3.4 DPMO ↔ 6σ, 6,210 DPMO ↔ 4σ, 66,807 DPMO ↔ 3σ.",tex:String.raw`\sigma_{\text{level}} = \Phi^{-1}\!\left(1 - \dfrac{${n(String.raw`\text{DPMO}`)}}{10^6}\right) + ${n("1.5")}`,variables:[{symbol:String.raw`\text{DPMO}`,meaning:"Long-term defects per million opportunities",unit:"DPMO"},{symbol:"1.5",meaning:"Conventional long-term to short-term shift",unit:"σ"}],whenToUse:["Discrete/attribute capability (defects, yields).","Translating yields or DPMO to a common sigma scale.","Long-term Z from Ppk: Z_LT = 3·Ppk (one side)."],units:"Sigma units (σ). It is a convention, not a measured standard deviation.",example:{title:"Billing accuracy",scenario:"Long-term billing performance is **6,210 DPMO**.",values:[{symbol:String.raw`\text{DPMO}`,value:"6,210",meaning:"long-term"},{symbol:"1.5",value:"1.5",meaning:"shift"}],substituted:String.raw`\Phi^{-1}(1 - 0.00621) + 1.5`,steps:[{tex:String.raw`\Phi^{-1}(0.99379) = ${t(w-1.5,2)}`,note:"Z table, read inward."},{tex:String.raw`${t(w-1.5,2)} + 1.5 = ${t(w,2)}`,note:"Add the shift."}],result:w,answer:`≈ ${e(w,2)}σ short-term`},solution:["Defect probability = 6,210 ÷ 10⁶ = 0.00621; yield = 0.99379.",`Z table: z ≈ ${e(w-1.5,2)}.`,`Add 1.5 → **${e(w,1)}σ**.`],trap:{title:"Which way is the shift?",body:"DPMO tables list SHORT-term sigma levels against LONG-term DPMO. Going from DPMO to sigma level you **add** 1.5; going from a target sigma level to allowed DPMO you **subtract** 1.5 first."},incorrect:{calculation:String.raw`\Phi^{-1}(0.99379) = ${t(w-1.5,2)}`,result:`${e(w-1.5,2)}σ`,whyWrong:"That is the long-term Z. The reported sigma level adds the 1.5σ shift.",correct:String.raw`${t(w-1.5,2)} + 1.5 = ${t(w,2)}`,correctResult:`${e(w,2)}σ`},denominatorErrors:["Computing DPMO without opportunities (DPU × 10⁶).","Looking up the defect rate instead of the yield.","Forgetting or reversing the 1.5 shift."],related:["zscore","ppk","dpmo"],examTools:{tables:["Sigma ↔ DPMO conversion table",Z],keys:["DPMO ÷ 1,000,000 = defect probability; 1 − that = yield.","Find the yield inside the Z table, read z, then + 1.5."]},sources:[c("2.4.3"),r("book-201-300",223,"Sigma level / DPMO table and the 1.5σ shift"),r("book-201-300",225,"Discrete capability: DPU, DPMO and sigma")]},{id:"stderr",name:"Standard Error of the Mean",short:"Spread of sample means: s ÷ √n.",group:"analyze",phase:3,syllabusRef:"3.2.3",supplementary:!1,definition:"By the **Central Limit Theorem**, sample means vary less than individual values — their standard deviation is the **standard error**, σ/√n (estimated by s/√n). It underpins every confidence interval and t/z test.",tex:String.raw`SE_{\bar{x}} = \dfrac{${n("s")}}{\sqrt{${n("n")}}}`,altTex:[{label:"Proportion",tex:String.raw`SE_{\hat{p}} = \sqrt{\dfrac{\hat{p}(1 - \hat{p})}{n}}`},{label:"Difference of two means",tex:String.raw`SE = \sqrt{\dfrac{s_1^2}{n_1} + \dfrac{s_2^2}{n_2}}`}],variables:[{symbol:"s",meaning:"Sample standard deviation of individual values",unit:"data units"},{symbol:"n",meaning:"Sample size",unit:"count"}],whenToUse:["Quantifying how precisely x̄ estimates μ.","Building confidence intervals and test statistics.","Planning n: halving SE needs 4× the sample."],units:"Same units as the data.",example:{title:"Router-swap duration",scenario:"A sample of **36 router swaps** has s = **12 min**.",values:[{symbol:"s",value:"12",meaning:"min"},{symbol:"n",value:"36",meaning:"swaps"}],substituted:String.raw`SE = \dfrac{12}{\sqrt{36}}`,steps:[{tex:String.raw`\sqrt{36} = 6`,note:"Root of n."},{tex:String.raw`SE = 12 \div 6 = ${t(he,0)}`,note:"Divide."}],result:he,answer:`SE = ${e(he,0)} min`},solution:["√36 = 6.",`SE = 12 ÷ 6 = **${e(he,0)} min** — individual swaps vary by about 12 min, but the mean of 36 is pinned down to about ±2 min per SE.`],trap:{title:"√n, not n",body:"Quadrupling the sample only **halves** the standard error. Dividing by n makes the SE far too small."},incorrect:{calculation:String.raw`\dfrac{12}{36} = 0.33`,result:"0.33 min",whyWrong:"Divided by n. The spread of means shrinks with √n.",correct:String.raw`\dfrac{12}{\sqrt{36}} = 2`,correctResult:"2 min"},denominatorErrors:["n instead of √n.","Adding two SEs instead of adding their squares.","Forgetting the root for a proportion SE."],related:["stdev","ci","sampleSize","ttest1"],examTools:{tables:["No table needed"],keys:["n √ then s ÷ MR (store √n in memory).",Mt]},sources:[c("3.2.3"),r("book-201-300",278,"Standard error of the mean"),r("book-201-300",276,"Central Limit Theorem")]},{id:"ci",name:"Confidence Interval for a Mean",short:"x̄ ± critical value × standard error.",group:"analyze",phase:3,syllabusRef:"3.2.1",supplementary:!1,definition:"A confidence interval gives a range of plausible values for the population mean: **x̄ ± t·s/√n** (σ unknown, df = n − 1) or **x̄ ± z·σ/√n** (σ known or n large). 95% confidence means the method captures μ in 95% of repeated samples.",tex:String.raw`\bar{x} \pm ${n(String.raw`t_{\alpha/2,\,n-1}`)}\,\dfrac{${n("s")}}{\sqrt{${n("n")}}}`,altTex:[{label:"σ known",tex:String.raw`\bar{x} \pm z_{\alpha/2}\dfrac{\sigma}{\sqrt{n}}`},{label:"Proportion",tex:String.raw`\hat{p} \pm z_{\alpha/2}\sqrt{\dfrac{\hat{p}(1-\hat{p})}{n}}`}],variables:[{symbol:String.raw`t_{\alpha/2,\,n-1}`,meaning:"Two-sided critical t (95% → α/2 = 0.025)",unit:"—"},{symbol:"s",meaning:"Sample SD",unit:"data units"},{symbol:"n",meaning:"Sample size",unit:"count"}],whenToUse:["Estimating a baseline with its uncertainty.","Checking whether a target lies inside plausible values.","Use t unless σ is genuinely known."],units:"Same units as the data.",example:{title:"Router-replacement visit time",scenario:"**20 visits** gave x̄ = **45 min**, s = **10 min** (σ unknown).",values:[{symbol:String.raw`t_{\alpha/2,\,n-1}`,value:e(g.crit,3),meaning:"t₀.₀₂₅,19"},{symbol:"s",value:"10",meaning:"min"},{symbol:"n",value:"20",meaning:"visits"}],substituted:String.raw`45 \pm ${t(g.crit,3)} \times \dfrac{10}{\sqrt{20}}`,steps:[{tex:String.raw`SE = 10 \div ${t(Math.sqrt(20),3)} = ${t(10/Math.sqrt(20),3)}`,note:"Standard error."},{tex:String.raw`\text{margin} = ${t(g.crit,3)} \times ${t(10/Math.sqrt(20),3)} = ${t(g.margin,2)}`,note:"t × SE."},{tex:String.raw`(${t(g.lower,2)},\ ${t(g.upper,2)})`,note:"Interval."}],result:g.margin,answer:`95% CI: ${e(g.lower,2)} to ${e(g.upper,2)} min (margin ±${e(g.margin,2)})`},solution:["df = 19 → t₀.₀₂₅ = 2.093.",`SE = 10/√20 = ${e(10/Math.sqrt(20),3)}.`,`45 ± ${e(g.margin,2)} → **${e(g.lower,2)} to ${e(g.upper,2)} min**.`],trap:{title:"z or t?",body:`With σ unknown and n = 20, using z = 1.96 gives a margin of ${e(mt(.975)*10/Math.sqrt(20),2)} — too narrow. Use t with n − 1 df. For confidence levels other than 95%, change the critical value (90% → 1.645, 99% → 2.576 for z).`},incorrect:{calculation:String.raw`45 \pm 1.96 \times 10 = 45 \pm 19.6`,result:"25.4 to 64.6",whyWrong:"Used s instead of s/√n (and z instead of t).",correct:String.raw`45 \pm ${t(g.crit,3)} \times ${t(10/Math.sqrt(20),3)}`,correctResult:`${e(g.lower,2)} to ${e(g.upper,2)}`},denominatorErrors:["Forgetting √n.","z instead of t for small samples.","One-sided critical value for a two-sided interval."],related:["stderr","sampleSize","ttest1"],examTools:{tables:[K,Z],keys:["Read t at df = n − 1 in the column for α/2 = 0.025 (two-sided 95%).","Compute the margin once (store it), then x̄ − MR and x̄ + MR."]},sources:[c("3.2.1"),r("book-201-300",277,"Setup-time example: n = 20, mean 45, s = 10 — 95% of sample means within 2 SE")]},{id:"sampleSize",name:"Sample Size for Estimating a Mean",short:"n = (zσ/E)², always rounded up.",group:"analyze",phase:3,syllabusRef:"3.4.3",supplementary:!1,definition:"To estimate a mean within ±E with a chosen confidence, solve the margin formula for n: **n = (z·σ/E)²**, rounding **up**. For a proportion use n = z²p(1 − p)/E² (p = 0.5 if no estimate). For a test with power, add z_β: n = [(z_α/2 + z_β)σ/δ]².",tex:String.raw`n = \left(\dfrac{${n(String.raw`z_{\alpha/2}`)}\,${n(String.raw`\sigma`)}}{${n("E")}}\right)^{2}`,altTex:[{label:"Proportion",tex:String.raw`n = \dfrac{z_{\alpha/2}^2\,p(1-p)}{E^2}`},{label:"Test with power",tex:String.raw`n = \left(\dfrac{(z_{\alpha/2} + z_{\beta})\,\sigma}{\delta}\right)^2`}],variables:[{symbol:String.raw`z_{\alpha/2}`,meaning:"Two-sided critical z (95% → 1.96)",unit:"—"},{symbol:String.raw`\sigma`,meaning:"Estimated process SD",unit:"data units"},{symbol:"E",meaning:"Margin of error (half the interval width)",unit:"data units"}],whenToUse:["Planning data collection in Measure/Analyze.","Justifying sample sizes to stakeholders.",'Minitab "Power and Sample Size" does the same calculation for tests.'],units:"A whole number of units — always round up.",example:{title:"Call wait time study",scenario:"Estimate mean wait within **±2 s** at 95% confidence; σ ≈ **8 s**.",values:[{symbol:String.raw`z_{\alpha/2}`,value:"1.96",meaning:"95%"},{symbol:String.raw`\sigma`,value:"8",meaning:"s"},{symbol:"E",value:"2",meaning:"s"}],substituted:String.raw`n = \left(\dfrac{1.96 \times 8}{2}\right)^2`,steps:[{tex:String.raw`1.96 \times 8 \div 2 = 7.84`,note:"Inside the bracket."},{tex:String.raw`7.84^2 = ${t(7.84**2,2)}`,note:"Square."},{tex:String.raw`n = ${H}`,note:"Round UP."}],result:H,answer:`n = ${H} calls`},solution:["(1.96 × 8 ÷ 2) = 7.84.","7.84² = 61.47.",`Round up: **${H} calls**.`],trap:{title:"Width vs margin",body:'"An interval no wider than 4 s" means E = 2 s. Using the full width as E gives a sample four times too small.'},incorrect:{calculation:String.raw`\dfrac{1.96 \times 8}{2} = 7.84 \to 8`,result:"8",whyWrong:"Forgot to square.",correct:String.raw`7.84^2 = 61.47 \to ${H}`,correctResult:`${H}`},denominatorErrors:["Not squaring.","Rounding down.","Using the full interval width as E."],related:["ci","stderr","prop1"],examTools:{tables:[Z],keys:["Compute z × σ ÷ E, then x² (square key).","Always round UP, even 61.01 → 62."]},sources:[c("3.4.3"),r("book-301-400",299,"Sample size: three of difference, power, SD and n determine the fourth"),r("book-201-300",278,"Sample size and the precision of the mean")]},{id:"ttest1",name:"1-Sample t Test",short:"t = (x̄ − μ₀) ÷ (s/√n), df = n − 1.",group:"analyze",phase:3,syllabusRef:"3.4.1",supplementary:!1,definition:'Tests whether a population mean equals a target μ₀ when σ is unknown. The statistic counts how many standard errors x̄ lies from μ₀. Compare with the critical t (df = n − 1) or use the p-value: **if p < α reject H₀, otherwise fail to reject** (never "accept").',tex:String.raw`t = \dfrac{${n(String.raw`\bar{x}`)} - ${n(String.raw`\mu_0`)}}{${n("s")}/\sqrt{${n("n")}}}`,variables:[{symbol:String.raw`\bar{x}`,meaning:"Sample mean",unit:"data units"},{symbol:String.raw`\mu_0`,meaning:"Hypothesised mean / target",unit:"data units"},{symbol:"s",meaning:"Sample SD",unit:"data units"},{symbol:"n",meaning:"Sample size",unit:"count"}],whenToUse:["Is the process mean on target (SLA, standard)?","Continuous, roughly normal data (or n ≥ 30 by the CLT).",'One-tailed only when the claim has a direction ("reduces", "exceeds").'],units:"t is unit-free; df = n − 1.",example:{title:"Response-time SLA",scenario:"The SLA mean response target is **4 h**. **16 tickets**: x̄ = **4.6 h**, s = **1.2 h**. Two-sided, α = 0.05.",values:[{symbol:String.raw`\bar{x}`,value:"4.6",meaning:"h"},{symbol:String.raw`\mu_0`,value:"4",meaning:"h"},{symbol:"s",value:"1.2",meaning:"h"},{symbol:"n",value:"16",meaning:"tickets"}],substituted:String.raw`t = \dfrac{4.6 - 4}{1.2/\sqrt{16}}`,steps:[{tex:String.raw`SE = 1.2 \div 4 = 0.3`,note:"Standard error."},{tex:String.raw`t = 0.6 \div 0.3 = ${t(le.t,2)}`,note:"Statistic."},{tex:String.raw`t_{0.025,15} = ${t(ve(.975,15),3)}`,note:"Critical value."}],result:le.t,answer:`t = ${e(le.t,2)} < ${e(ve(.975,15),3)} (p = ${e(le.p,3)}) → fail to reject H₀`},solution:["SE = 1.2/√16 = 0.3.","t = (4.6 − 4)/0.3 = **2.00**, df = 15.",`Critical t = ${e(ve(.975,15),3)}; |t| < critical (p = ${e(le.p,3)}) → **fail to reject** H₀ at α = 0.05.`],trap:{title:"Fail to reject ≠ accept",body:"Not rejecting H₀ means the data are not strong enough to show a difference — it does not prove the mean equals 4 h. Also watch one- vs two-tailed wording: the one-tailed critical t (1.753 here) would reject."},incorrect:{calculation:String.raw`t = \dfrac{0.6}{1.2} = 0.5`,result:"0.5",whyWrong:"Divided by s instead of the standard error s/√n.",correct:String.raw`t = \dfrac{0.6}{0.3} = 2.0`,correctResult:"2.00"},denominatorErrors:["s instead of s/√n.","df = n instead of n − 1.","z critical value (1.96) for small samples."],related:["stderr","ci","ttest2","pairedT"],examTools:{tables:[K],keys:["Two-sided: look up the α/2 column; one-sided: the α column.","Compute SE first (s ÷ √n → M+), then (x̄ − μ₀) ÷ MR."]},sources:[c("3.4.1"),r("book-301-400",298,"1-sample t test"),r("book-301-400",302,"1-sample t example and interpretation")]},{id:"ttest2",name:"2-Sample t Test",short:"Compare two independent means — Welch by default, pooled if variances are equal.",group:"analyze",phase:3,syllabusRef:"3.4.1",supplementary:!1,definition:"Compares the means of two **independent** groups. Minitab's default (Welch) does not assume equal variances: SE = √(s₁²/n₁ + s₂²/n₂) with Welch–Satterthwaite df. If an F/Levene test supports equal variances, the **pooled** version uses sₚ and df = n₁ + n₂ − 2.",tex:String.raw`t = \dfrac{${n(String.raw`\bar{x}_1`)} - ${n(String.raw`\bar{x}_2`)}}{\sqrt{\dfrac{${n("s_1^2")}}{n_1} + \dfrac{${n("s_2^2")}}{n_2}}}`,altTex:[{label:"Pooled (equal variances)",tex:String.raw`t = \dfrac{\bar{x}_1 - \bar{x}_2}{s_p\sqrt{1/n_1 + 1/n_2}},\quad s_p^2 = \dfrac{(n_1-1)s_1^2 + (n_2-1)s_2^2}{n_1+n_2-2}`}],variables:[{symbol:String.raw`\bar{x}_1, \bar{x}_2`,meaning:"Sample means of the two groups",unit:"data units"},{symbol:"s_1^2, s_2^2",meaning:"Sample variances",unit:"units²"}],whenToUse:["Two vendors, two shifts, old vs new method — different units in each group.","Check normality and equal variances first.","If the same units are measured twice, use the paired t instead."],units:"t unit-free; Welch df is usually not a whole number.",example:{title:"Two repair vendors",scenario:"Vendor A: n = **12**, x̄ = **38.2 h**, s = **4.1**. Vendor B: n = **10**, x̄ = **34.5 h**, s = **6.3**. Variances not assumed equal.",values:[{symbol:String.raw`\bar{x}_1 - \bar{x}_2`,value:"3.7",meaning:"h"},{symbol:"s_1^2/n_1",value:e(4.1**2/12,3),meaning:""},{symbol:"s_2^2/n_2",value:e(6.3**2/10,3),meaning:""}],substituted:String.raw`t = \dfrac{38.2 - 34.5}{\sqrt{${t(4.1**2/12,3)} + ${t(6.3**2/10,3)}}}`,steps:[{tex:String.raw`SE = \sqrt{${t(4.1**2/12+6.3**2/10,3)}} = ${t(Math.sqrt(4.1**2/12+6.3**2/10),3)}`,note:"Welch SE."},{tex:String.raw`t = 3.7 \div ${t(Math.sqrt(4.1**2/12+6.3**2/10),3)} = ${t(v.t,2)}`,note:"Statistic."},{tex:String.raw`df \approx ${t(v.df,1)},\ p = ${t(v.p,3)}`,note:"Welch df and p."}],result:v.t,answer:`t = ${e(v.t,2)}, df ≈ ${e(v.df,1)}, p = ${e(v.p,3)} → fail to reject at α = 0.05`},solution:[`SE = √(${e(4.1**2/12,3)} + ${e(6.3**2/10,3)}) = ${e(Math.sqrt(4.1**2/12+6.3**2/10),3)}.`,`t = 3.7 ÷ SE = **${e(v.t,2)}**; Welch df ≈ ${e(v.df,1)}.`,`p = ${e(v.p,3)} > 0.05 → no significant difference shown. (Pooled would give t = ${e(kt.t,2)}, df = 20.)`],trap:{title:"Pooled vs Welch, independent vs paired",body:"Pool only when variances are shown to be equal. And if the same agents/routers are measured before and after, the samples are **not** independent — a 2-sample t throws away the pairing and loses power."},incorrect:{calculation:String.raw`\dfrac{3.7}{\dfrac{4.1}{\sqrt{12}} + \dfrac{6.3}{\sqrt{10}}} = ${t(3.7/(4.1/Math.sqrt(12)+6.3/Math.sqrt(10)),2)}`,result:e(3.7/(4.1/Math.sqrt(12)+6.3/Math.sqrt(10)),2),whyWrong:"Added the two standard errors. Variances add; SEs do not.",correct:String.raw`\dfrac{3.7}{\sqrt{${t(4.1**2/12,3)} + ${t(6.3**2/10,3)}}} = ${t(v.t,2)}`,correctResult:e(v.t,2)},denominatorErrors:["Adding SEs instead of variances.","Pooled df n₁ + n₂ − 2 with a Welch statistic.","Leaving n out of each variance term."],related:["ttest1","pairedT","anova","stderr"],examTools:{tables:[K,Le+" — equal-variance F test"],keys:["Compute s₁²/n₁ and s₂²/n₂ separately (M+ each), then MR √.","Pooled df = n₁ + n₂ − 2; if Welch df is not whole, round DOWN when using a table."]},sources:[c("3.4.1"),r("book-301-400",309,"2-sample t test"),r("book-301-400",316,"Equal variances and the 2-sample t"),r("book-301-400",324,"Pooled standard deviation")]},{id:"pairedT",name:"Paired t Test",short:"A 1-sample t on the differences: d̄ ÷ (s_d/√n).",group:"analyze",phase:3,syllabusRef:"3.4.1",supplementary:!1,definition:"When each unit is measured twice (before/after, two methods on the same item), analyse the **differences**. The paired t is a 1-sample t test of the mean difference against 0, with df = number of pairs − 1. Pairing removes unit-to-unit variation, so it is far more sensitive than a 2-sample t.",tex:String.raw`t = \dfrac{${n(String.raw`\bar{d}`)}}{${n("s_d")}/\sqrt{${n("n")}}}`,variables:[{symbol:String.raw`\bar{d}`,meaning:"Mean of the paired differences",unit:"data units"},{symbol:"s_d",meaning:"SD of the differences",unit:"data units"},{symbol:"n",meaning:"Number of PAIRS",unit:"count"}],whenToUse:["Before/after on the same agents, sites, routers.","Two measurement methods on the same parts.","Differences roughly normal."],units:"t unit-free; df = pairs − 1.",example:{title:"Coaching and handle time",scenario:`Eight agents' AHT before (**${j.join(", ")}**) and after (**${G.join(", ")}**) coaching.`,values:[{symbol:String.raw`\bar{d}`,value:e(h.meanDiff,3),meaning:"min"},{symbol:"s_d",value:e(h.sdDiff,4),meaning:"min"},{symbol:"n",value:"8",meaning:"pairs"}],substituted:String.raw`t = \dfrac{${t(h.meanDiff,2)}}{${t(h.sdDiff,4)}/\sqrt{8}}`,steps:[{tex:String.raw`d = ${j.map((i,l)=>i-G[l]).join(",\\,")}`,note:"Differences."},{tex:String.raw`\bar{d} = ${t(h.meanDiff,2)},\ s_d = ${t(h.sdDiff,4)}`,note:"Describe d."},{tex:String.raw`t = ${t(h.t,2)},\ df = 7`,note:"Statistic."}],result:h.t,answer:`t = ${e(h.t,2)}, p = ${e(h.p,4)} → reject H₀: coaching reduced AHT`},solution:["Differences: 3, 1, 4, 2, 3, 1, 2, 4 → d̄ = 2.5.",`s_d = ${e(h.sdDiff,4)}; SE = s_d/√8 = ${e(h.sdDiff/Math.sqrt(8),4)}.`,`t = **${e(h.t,2)}**, df = 7, p = ${e(h.p,4)} < 0.05 → reject H₀.`],trap:{title:"Count pairs, not observations",body:"Eight agents measured twice is **8 pairs** (df = 7), not 16 observations (df = 14). An independent 2-sample t on these data would give a much smaller t because agent-to-agent differences swamp the effect."},incorrect:{calculation:String.raw`t_{\text{2-sample}} = ${t(we(y(j),se(j),8,y(G),se(G),8,!0).t,2)}`,result:e(we(y(j),se(j),8,y(G),se(G),8,!0).t,2),whyWrong:"Treated the before/after samples as independent and lost the pairing.",correct:String.raw`t_{\text{paired}} = ${t(h.t,2)}`,correctResult:e(h.t,2)},denominatorErrors:["df = 2n − 2.","Forgetting √n.","Combining the before and after SDs instead of computing s_d."],related:["ttest1","ttest2","stdev"],examTools:{tables:[K],keys:["Write the differences column first; then use the calculator's statistics mode on d only.",$e]},sources:[c("3.4.1"),r("book-301-400",329,"Paired t test"),r("book-301-400",331,"Paired t example")]},{id:"anova",name:"One-Way ANOVA",short:"F = MS(Between) ÷ MS(Within) — are any of k means different?",group:"analyze",phase:3,syllabusRef:"3.4.3",supplementary:!1,definition:"One-way ANOVA tests whether **k ≥ 3** group means are all equal by comparing variation **between** group means with variation **within** groups. Each mean square is SS ÷ df. A large F (small p) means at least one mean differs — it does not say which.",tex:String.raw`F = \dfrac{${n(String.raw`SS_B`)}/(${n("k")}-1)}{${n(String.raw`SS_W`)}/(${n("N")}-k)} = \dfrac{MS_B}{MS_W}`,altTex:[{label:"Sums of squares",tex:String.raw`SS_B = \sum n_i(\bar{x}_i - \bar{\bar{x}})^2,\quad SS_W = \sum\sum (x_{ij} - \bar{x}_i)^2`},{label:"R²",tex:String.raw`R^2 = SS_B / SS_T`}],variables:[{symbol:"SS_B",meaning:"Between-groups (factor) sum of squares",unit:"units²"},{symbol:"SS_W",meaning:"Within-groups (error) sum of squares",unit:"units²"},{symbol:"k",meaning:"Number of groups",unit:"count"},{symbol:"N",meaning:"Total observations",unit:"count"}],whenToUse:["Comparing 3+ regions, vendors, shifts.","Assumptions: normal residuals, equal variances (Bartlett/Levene), independence.","Avoids the inflated α of many pairwise t tests."],units:"F unit-free with (k − 1, N − k) df.",example:{title:"Resolution time by site",scenario:"Three support sites, five tickets each: A = 23, 25, 21, 24, 22; B = 28, 27, 30, 26, 29; C = 22, 24, 23, 25, 21.",values:[{symbol:"SS_B",value:e(m.ssb,2),meaning:"df 2"},{symbol:"SS_W",value:e(m.ssw,0),meaning:"df 12"},{symbol:"k",value:"3",meaning:"sites"},{symbol:"N",value:"15",meaning:"tickets"}],substituted:String.raw`F = \dfrac{${t(m.ssb,2)}/2}{30/12}`,steps:[{tex:String.raw`MS_B = ${t(m.msb,2)}`,note:"SS_B ÷ (k − 1)."},{tex:String.raw`MS_W = 30 \div 12 = 2.5`,note:"SS_W ÷ (N − k)."},{tex:String.raw`F = ${t(m.F,2)} > F_{0.05}(2,12) = ${t(qe,2)}`,note:"Compare."}],result:m.F,answer:`F = ${e(m.F,2)}, p = ${e(m.p,4)} → at least one site differs (R² = ${e(m.rSq*100,1)}%)`},solution:["Means 23, 28, 23; grand mean 24.67.",`SS_B = 5[(23 − 24.67)² + (28 − 24.67)² + (23 − 24.67)²] = ${e(m.ssb,2)}; SS_W = 10 + 10 + 10 = 30.`,`F = (${e(m.ssb,2)}/2) ÷ (30/12) = **${e(m.F,2)}** > ${e(qe,2)} → reject H₀.`],trap:{title:"MS = SS ÷ df",body:'Dividing SS_B by SS_W directly, or using N − 1 for the error df, are the classic slips. And remember: a significant F says "not all equal" — follow up with comparisons/main-effects plots to see which.'},incorrect:{calculation:String.raw`F = ${t(m.ssb,2)} \div 30 = ${t(m.ssb/m.ssw,2)}`,result:e(m.ssb/m.ssw,2),whyWrong:"Divided sums of squares — they must first be turned into mean squares.",correct:String.raw`F = ${t(m.msb,2)} \div 2.5 = ${t(m.F,2)}`,correctResult:e(m.F,2)},denominatorErrors:["Error df = N − 1 (that is total df).","Factor df = k (should be k − 1).","Swapping numerator/denominator df in the F table."],related:["ttest2","chisq","rsq"],examTools:{tables:[Le+" — numerator df = k − 1 (columns), denominator df = N − k (rows)"],keys:["Build the table: Source | SS | df | MS | F.","Group means → SS_B with M+ for each nᵢ(x̄ᵢ − x̿)²."]},sources:[c("3.4.3"),r("book-301-400",337,"One-way ANOVA overview"),r("book-301-400",358,"ANOVA session window: DF, SS, MS, F, P")]},{id:"chisq",name:"Chi-Square Test of Independence",short:"Σ (O − E)² ÷ E with E = row × column ÷ N.",group:"analyze",phase:3,syllabusRef:"3.5.8",supplementary:!1,definition:"Tests whether two categorical variables are independent (e.g. outcome vs channel). Expected counts assume independence: **E = row total × column total ÷ grand total**. Large χ² (small p) means the variables are associated. df = (r − 1)(c − 1). Expected counts should generally be ≥ 5.",tex:String.raw`\chi^2 = \sum \dfrac{(${n("O")} - ${n("E")})^2}{${n("E")}},\quad E = \dfrac{\text{row} \times \text{col}}{N}`,variables:[{symbol:"O",meaning:"Observed count in a cell",unit:"count"},{symbol:"E",meaning:"Expected count under independence",unit:"count"}],whenToUse:["Discrete Y vs discrete X (contingency tables).","Goodness of fit against expected proportions (df = categories − 1).","Not for percentages — use the counts."],units:"χ² unit-free; df = (r − 1)(c − 1).",example:{title:"Ticket outcome by channel",scenario:"App: 30 resolved, 20 escalated, 10 vendor. Phone: 20 resolved, 25 escalated, 35 vendor (N = 140).",values:[{symbol:"O",value:"30",meaning:"App × resolved"},{symbol:"E",value:e(b.expected[0][0],3),meaning:"60 × 50 ÷ 140"}],substituted:String.raw`\chi^2 = \dfrac{(30 - ${t(b.expected[0][0],2)})^2}{${t(b.expected[0][0],2)}} + \dots`,steps:[{tex:String.raw`E_{11} = 60 \times 50 \div 140 = ${t(b.expected[0][0],2)}`,note:"Expected count."},{tex:String.raw`\chi^2 = ${t(b.chi2,2)},\ df = 2`,note:"Sum all six cells."},{tex:String.raw`${t(b.chi2,2)} > \chi^2_{0.05,2} = ${t(Oe,3)}`,note:"Compare."}],result:b.chi2,answer:`χ² = ${e(b.chi2,2)}, p = ${e(b.p,4)} → outcome depends on channel`},solution:[`Expected counts: ${b.expected.flat().map(i=>e(i,2)).join(", ")}.`,`χ² = Σ(O − E)²/E = **${e(b.chi2,2)}**, df = (2 − 1)(3 − 1) = 2.`,`Critical value ${e(Oe,3)} → reject independence.`],trap:{title:"Divide by E, and df = (r − 1)(c − 1)",body:"Dividing by the observed count, using equal expected counts, or taking df = cells − 1 (the goodness-of-fit df) are the usual errors."},incorrect:{calculation:String.raw`E_{11} = 140 \div 6 = 23.33`,result:"23.33",whyWrong:"Spread the total equally over cells. Expected counts follow the row and column totals.",correct:String.raw`E_{11} = \dfrac{60 \times 50}{140} = ${t(b.expected[0][0],2)}`,correctResult:e(b.expected[0][0],2)},denominatorErrors:["Dividing by O instead of E.","df = r × c − 1.","Running the test on percentages rather than counts."],related:["prop1","anova"],examTools:{tables:[Ct],keys:["Fill an expected-count grid first; check the row and column sums match.","Accumulate each (O − E)² ÷ E with M+."]},sources:[c("3.5.8"),r("book-401-500",406,"Chi-square test statistic, expected counts and df = (r − 1)(c − 1)"),r("book-401-500",408,"Contingency table example")]},{id:"prop1",name:"Proportion z Test",short:"z = (p̂ − p₀) ÷ √[p₀(1 − p₀)/n].",group:"analyze",phase:3,syllabusRef:"3.5.7",supplementary:!1,definition:"Tests a proportion against a target (SLA compliance, first-contact resolution). Under H₀ the standard error uses **p₀**. The two-proportion version pools both samples: p̄ = (x₁ + x₂)/(n₁ + n₂). Requires np₀ and n(1 − p₀) ≥ 5 for the normal approximation.",tex:String.raw`z = \dfrac{${n(String.raw`\hat{p}`)} - ${n("p_0")}}{\sqrt{\dfrac{${n("p_0")}(1 - ${n("p_0")})}{${n("n")}}}}`,altTex:[{label:"Two proportions (pooled)",tex:String.raw`z = \dfrac{\hat{p}_1 - \hat{p}_2}{\sqrt{\bar{p}(1-\bar{p})\left(\frac{1}{n_1} + \frac{1}{n_2}\right)}}`}],variables:[{symbol:String.raw`\hat{p}`,meaning:"Sample proportion x/n",unit:"fraction"},{symbol:"p_0",meaning:"Hypothesised proportion (target)",unit:"fraction"},{symbol:"n",meaning:"Sample size",unit:"count"}],whenToUse:["Discrete pass/fail data vs a target.","Comparing two proportions (before/after, two vendors).","Large samples (normal approximation)."],units:"z unit-free.",example:{title:"P3 on-time resolution",scenario:"Target: **90%** of P3 tickets on time. Audit: **171 of 200** on time.",values:[{symbol:String.raw`\hat{p}`,value:"0.855",meaning:"171/200"},{symbol:"p_0",value:"0.90",meaning:"target"},{symbol:"n",value:"200",meaning:"tickets"}],substituted:String.raw`z = \dfrac{0.855 - 0.90}{\sqrt{0.9 \times 0.1 / 200}}`,steps:[{tex:String.raw`SE = \sqrt{0.00045} = ${t(Math.sqrt(45e-5),4)}`,note:"Use p₀."},{tex:String.raw`z = -0.045 \div ${t(Math.sqrt(45e-5),4)} = ${t(U.z,2)}`,note:"Statistic."}],result:U.z,answer:`z = ${e(U.z,2)}, two-sided p = ${e(U.p,4)} → reject H₀: compliance is below 90%`},solution:["p̂ = 171/200 = 0.855.",`SE = √(0.9 × 0.1/200) = ${e(Math.sqrt(45e-5),4)}.`,`z = **${e(U.z,2)}**; |z| > 1.96 → reject H₀ (p = ${e(U.p,4)}).`],trap:{title:"p₀ in the SE, and success vs failure",body:"The test statistic assumes H₀ is true, so the SE uses p₀, not p̂. And if the stem gives breaches, convert to the on-time count before comparing with an on-time target."},incorrect:{calculation:String.raw`\dfrac{-0.045}{\sqrt{0.855 \times 0.145/200}} = ${t(-.045/Math.sqrt(.855*.145/200),2)}`,result:e(-.045/Math.sqrt(.855*.145/200),2),whyWrong:"Used p̂ in the standard error (that is the CI formula).",correct:String.raw`\dfrac{-0.045}{\sqrt{0.9 \times 0.1/200}} = ${t(U.z,2)}`,correctResult:e(U.z,2)},denominatorErrors:["p̂ instead of p₀ in the SE.","Unpooled SE in a two-proportion test.","Forgetting the square root."],related:["chisq","ci","sampleSize","pchart"],examTools:{tables:[Z],keys:["p₀ × (1 − p₀) ÷ n, then √ → store; then (p̂ − p₀) ÷ MR.","Compare |z| with 1.96 (two-sided 5%) or 1.645 (one-sided 5%)."]},sources:[c("3.5.7"),r("book-401-500",398,"One- and two-sample proportion tests"),r("book-401-500",400,"Proportion vs target example and sample size")]},{id:"correlation",name:"Pearson Correlation r",short:"Strength and direction of a LINEAR relationship, −1 to +1.",group:"improve",phase:4,syllabusRef:"4.1.1",supplementary:!1,definition:"Pearson's r measures how closely paired data follow a straight line. r = Sxy/√(Sxx·Syy). It is unit-free, between −1 and +1, and says nothing about cause — a strong r can come from a lurking variable.",tex:String.raw`r = \dfrac{${n("S_{xy}")}}{\sqrt{${n("S_{xx}")}\,${n("S_{yy}")}}}`,altTex:[{label:"Sums",tex:String.raw`S_{xy} = \sum (x-\bar{x})(y-\bar{y}),\ S_{xx} = \sum (x-\bar{x})^2,\ S_{yy} = \sum (y-\bar{y})^2`}],variables:[{symbol:"S_{xy}",meaning:"Sum of cross-products about the means",unit:"x·y units"},{symbol:"S_{xx}, S_{yy}",meaning:"Sums of squares of x and y",unit:"units²"}],whenToUse:["Screening a continuous X against a continuous Y.","Always plot the scatter first — r misses curves and outliers.","Test H₀: ρ = 0 with t = r√(n − 2)/√(1 − r²)."],units:"Unit-free, −1 ≤ r ≤ 1.",example:{title:"Cable distance vs repair time",scenario:`Distance to fault (km): ${z.join(", ")}; repair time (h): ${k.join(", ")}.`,values:[{symbol:"S_{xy}",value:e(de,2),meaning:""},{symbol:"S_{xx}, S_{yy}",value:`${e(ce,0)}, ${e(s.sst,2)}`,meaning:""}],substituted:String.raw`r = \dfrac{${t(de,2)}}{\sqrt{${t(ce,0)} \times ${t(s.sst,2)}}}`,steps:[{tex:String.raw`r = ${t(M.r,4)}`,note:"Very strong positive."},{tex:String.raw`r^2 = ${t(M.rSq,4)}`,note:"Share explained by a line."}],result:M.r,answer:`r = ${e(M.r,3)} (p < 0.001)`},solution:[`x̄ = 6, ȳ = ${e(y(k),3)}; Sxx = ${e(ce,0)}, Sxy = ${e(de,2)}, Syy = ${e(s.sst,2)}.`,`r = **${e(M.r,3)}**.`,"Strong linear association — causation still needs process knowledge or an experiment."],trap:{title:"Correlation ≠ causation; r ≠ R²",body:"A strong r does not prove X drives Y. And r² (not r) is the share of variation explained: r = 0.7 explains only 49%."},incorrect:{calculation:String.raw`r = S_{xy}/S_{xx} = ${t(s.b1,3)}`,result:e(s.b1,3),whyWrong:"That is the regression slope (with units), not the correlation.",correct:String.raw`r = S_{xy}/\sqrt{S_{xx}S_{yy}} = ${t(M.r,3)}`,correctResult:e(M.r,3)},denominatorErrors:["Forgetting the square root.","Dividing by Sxx only (slope).","Dropping the sign."],related:["regression","rsq"],examTools:{tables:[K+" — for testing ρ = 0 with n − 2 df"],keys:["Many calculators have a linear-regression (a+bx) mode: read r directly.","By hand: table of (x − x̄), (y − ȳ), their product and squares; sum each column."]},sources:[c("4.1.1"),r("book-401-500",427,"Correlation"),r("book-401-500",432,"Correlation coefficient output and p-value")]},{id:"regression",name:"Simple Linear Regression",short:"ŷ = b₀ + b₁x with b₁ = Sxy/Sxx and b₀ = ȳ − b₁x̄.",group:"improve",phase:4,syllabusRef:"4.1.2",supplementary:!1,definition:"Least squares fits the line that minimises the sum of squared residuals. The slope b₁ is the change in Y per unit of X; the intercept b₀ is the prediction at x = 0. Residuals e = y − ŷ must look random (normal, constant spread, no pattern) for the model to be trusted.",tex:String.raw`\hat{y} = ${n("b_0")} + ${n("b_1")}x,\quad b_1 = \dfrac{S_{xy}}{S_{xx}},\ b_0 = \bar{y} - b_1\bar{x}`,altTex:[{label:"Residual",tex:String.raw`e_i = y_i - \hat{y}_i`},{label:"Prediction interval at x₀",tex:String.raw`\hat{y}_0 \pm t_{\alpha/2,n-2}\,s\sqrt{1 + \tfrac{1}{n} + \tfrac{(x_0 - \bar{x})^2}{S_{xx}}}`}],variables:[{symbol:"b_0",meaning:"Intercept (ŷ at x = 0)",unit:"y units"},{symbol:"b_1",meaning:"Slope (change in y per unit x)",unit:"y units per x unit"}],whenToUse:["Quantifying how a continuous X drives Y (Improve).","Predicting Y within the range of observed X.","Confidence interval = mean response; prediction interval = a single new value (wider)."],units:"b₀ in y units; b₁ in y units per x unit.",example:{title:"Repair-time model",scenario:`Same data: distance ${z.join(", ")} km; repair time ${k.join(", ")} h.`,values:[{symbol:"b_1",value:e(s.b1,4),meaning:"h per km"},{symbol:"b_0",value:e(s.b0,4),meaning:"h"}],substituted:String.raw`b_1 = \dfrac{${t(de,2)}}{${t(ce,0)}},\ b_0 = ${t(y(k),3)} - b_1 \times 6`,steps:[{tex:String.raw`b_1 = ${t(s.b1,4)}`,note:"Slope."},{tex:String.raw`b_0 = ${t(s.b0,4)}`,note:"Intercept."},{tex:String.raw`\hat{y}(6) = ${t(s.predict(6),3)}`,note:"Predict at 6 km."}],result:s.b1,answer:`ŷ = ${e(s.b0,3)} + ${e(s.b1,3)}x; at 6 km ŷ = ${e(s.predict(6),2)} h (95% PI ${e(s.intervals(6).pi[0],2)}–${e(s.intervals(6).pi[1],2)})`},solution:[`b₁ = Sxy/Sxx = ${e(de,2)}/${e(ce,0)} = **${e(s.b1,3)}** h per km.`,`b₀ = ${e(y(k),3)} − ${e(s.b1,3)} × 6 = **${e(s.b0,3)}** h.`,`Prediction at 6 km: ${e(s.predict(6),2)} h.`],trap:{title:"Slope/intercept swap and extrapolation",body:"The coefficient that multiplies x is the slope. And never predict far outside the observed X range — the line was only fitted there."},incorrect:{calculation:String.raw`b_0 = \bar{y} = ${t(y(k),2)}`,result:e(y(k),2),whyWrong:"ȳ is the prediction at x̄, not at x = 0.",correct:String.raw`b_0 = \bar{y} - b_1\bar{x} = ${t(s.b0,2)}`,correctResult:e(s.b0,2)},denominatorErrors:["b₁ = Sxy/Syy (regresses x on y).","Residual as ŷ − y (sign).","Using n − 1 instead of n − 2 for the residual SD."],related:["correlation","rsq"],examTools:{tables:[K+" — slope test and intervals use n − 2 df"],keys:["Calculator regression mode (a + bx): a = intercept, b = slope.","Predict by typing b0 + b1 × x — keep coefficients unrounded in memory."]},sources:[c("4.1.2"),r("book-401-500",433,"Regression equation output"),r("book-401-500",454,"Confidence and prediction intervals")]},{id:"rsq",name:"Coefficient of Determination R²",short:"Share of Y variation explained by the model.",group:"improve",phase:4,syllabusRef:"4.1.3",supplementary:!1,definition:"R² = SS(Regression) ÷ SS(Total) = 1 − SSE/SST. In simple linear regression it equals r². It never decreases when predictors are added, which is why multiple regression also reports **adjusted R²**.",tex:String.raw`R^2 = \dfrac{${n(String.raw`SS_{\text{reg}}`)}}{${n(String.raw`SS_{\text{total}}`)}} = 1 - \dfrac{SS_{\text{error}}}{SS_{\text{total}}}`,altTex:[{label:"Adjusted",tex:String.raw`R^2_{\text{adj}} = 1 - (1 - R^2)\dfrac{n-1}{n-p-1}`}],variables:[{symbol:String.raw`SS_{\text{reg}}`,meaning:"Variation explained by the model",unit:"y units²"},{symbol:String.raw`SS_{\text{total}}`,meaning:"Total variation of y about its mean",unit:"y units²"}],whenToUse:["Judging practical usefulness of a regression.",'Reading Minitab "R-sq" and "R-sq(adj)".',"Comparing models on the same Y."],units:"Percentage (or fraction) from 0 to 100%.",example:{title:"Repair-time model fit",scenario:`For the repair-time line, SST = ${e(s.sst,3)} and SSE = ${e(s.sse,3)}.`,values:[{symbol:String.raw`SS_{\text{reg}}`,value:e(s.sst-s.sse,3),meaning:"explained"},{symbol:String.raw`SS_{\text{total}}`,value:e(s.sst,3),meaning:"total"}],substituted:String.raw`R^2 = \dfrac{${t(s.sst-s.sse,3)}}{${t(s.sst,3)}}`,steps:[{tex:String.raw`R^2 = ${t(s.rSq,4)}`,note:"Ratio."},{tex:String.raw`= r^2 = ${t(M.r,4)}^2`,note:"Simple regression check."}],result:s.rSq*100,answer:`R² = ${e(s.rSq*100,1)}% (adjusted ${e(s.rSqAdj*100,1)}%)`},solution:[`SSR = SST − SSE = ${e(s.sst-s.sse,3)}.`,`R² = ${e(s.sst-s.sse,3)} ÷ ${e(s.sst,3)} = **${e(s.rSq*100,1)}%**.`,`Equals r² = ${e(M.r,4)}².`],trap:{title:"r vs R²",body:"r = 0.8 means R² = 64%, not 80%. And a high R² does not make a model valid — check the residual plots."},incorrect:{calculation:String.raw`SSE/SST = ${t(s.sse/s.sst,4)}`,result:e(s.sse/s.sst*100,1)+"%",whyWrong:"That is the UNEXPLAINED share.",correct:String.raw`1 - SSE/SST = ${t(s.rSq,4)}`,correctResult:e(s.rSq*100,1)+"%"},denominatorErrors:["Dividing by SSE instead of SST.","Reporting r instead of r².","Using MS instead of SS."],related:["correlation","regression","anova"],examTools:{tables:["No table needed"],keys:["SSR ÷ (SSR + SSE) × 100.","From r: r x² × 100."]},sources:[c("4.1.3"),r("book-401-500",433,"R-Sq in regression output"),r("book-401-500",448,"R-Sq and R-Sq(adj)")]},{id:"xbarR",name:"Xbar-R Chart Limits",short:"x̿ ± A₂R̄ for means; D₃R̄ and D₄R̄ for ranges.",group:"control",phase:5,syllabusRef:"5.2.3",supplementary:!1,definition:"For subgroups of size n (typically 2–9), the Xbar chart tracks subgroup means and the R chart tracks subgroup ranges. Control limits come from the process itself — x̿ and R̄ with constants A₂, D₃, D₄ that depend on **n** (subgroup size, not the number of subgroups).",tex:String.raw`\text{UCL}_{\bar{x}} = ${n(String.raw`\bar{\bar{x}}`)} + ${n("A_2")}\,${n(String.raw`\overline{R}`)},\quad \text{LCL}_{\bar{x}} = \bar{\bar{x}} - A_2\overline{R}`,altTex:[{label:"R chart",tex:String.raw`\text{UCL}_R = D_4\overline{R},\quad \text{LCL}_R = D_3\overline{R}`}],variables:[{symbol:String.raw`\bar{\bar{x}}`,meaning:"Grand mean of subgroup means (centre line)",unit:"data units"},{symbol:"A_2",meaning:"Constant for subgroup size n",unit:"—"},{symbol:String.raw`\overline{R}`,meaning:"Average subgroup range",unit:"data units"}],whenToUse:["Continuous data collected in rational subgroups (e.g. 5 calls per hour).","Use Xbar-S for n > 9.","Establish limits from a stable baseline; read the R chart first."],units:"Same units as the data.",example:{title:"Hourly handle-time subgroups",scenario:"Three subgroups of five calls (min): 10, 12, 11, 13, 9 | 11, 11, 12, 10, 13 | 12, 14, 10, 11, 12.",values:[{symbol:String.raw`\bar{\bar{x}}`,value:e(u.xbar.cl,2),meaning:"mean of 11, 11.4, 11.8"},{symbol:"A_2",value:"0.577",meaning:"n = 5"},{symbol:String.raw`\overline{R}`,value:e(u.r.cl,4),meaning:"mean of 4, 3, 4"}],substituted:String.raw`\text{UCL} = 11.4 + 0.577 \times ${t(u.r.cl,4)}`,steps:[{tex:String.raw`A_2\overline{R} = ${t(.577*u.r.cl,4)}`,note:"Half-width."},{tex:String.raw`\text{UCL}_{\bar{x}} = ${t(u.xbar.ucl,3)},\ \text{LCL}_{\bar{x}} = ${t(u.xbar.lcl,3)}`,note:"Xbar limits."},{tex:String.raw`\text{UCL}_R = 2.114 \times ${t(u.r.cl,4)} = ${t(u.r.ucl,3)}`,note:"R chart (LCL = 0)."}],result:u.xbar.ucl,answer:`Xbar: ${e(u.xbar.lcl,2)} – ${e(u.xbar.ucl,2)} min; R: 0 – ${e(u.r.ucl,2)} min`},solution:["Subgroup means 11, 11.4, 11.8 → x̿ = 11.4; ranges 4, 3, 4 → R̄ = 3.667.","n = 5: A₂ = 0.577, D₃ = 0, D₄ = 2.114.",`UCL = **${e(u.xbar.ucl,2)}**, LCL = ${e(u.xbar.lcl,2)}; R chart UCL = ${e(u.r.ucl,2)}.`],trap:{title:"Control limits are not spec limits",body:"Limits are the voice of the process (x̿ ± A₂R̄). Specification limits are the voice of the customer and never appear on an Xbar chart. Also read the constants for the subgroup size n, not the number of subgroups."},incorrect:{calculation:String.raw`11.4 + 3 \times ${t(u.r.cl,3)} = ${t(11.4+3*u.r.cl,2)}`,result:e(11.4+3*u.r.cl,2),whyWrong:"Used 3R̄. R̄ must be converted to σ/√n — that is what A₂ does.",correct:String.raw`11.4 + 0.577 \times ${t(u.r.cl,3)} = ${t(u.xbar.ucl,2)}`,correctResult:e(u.xbar.ucl,2)},denominatorErrors:["Constant for the number of subgroups instead of n.","D₄ on the Xbar chart (it is for R).","Using the overall SD of all readings."],related:["imr","cp","pchart"],examTools:{tables:[ye],keys:["Find the row for your subgroup size n; read A₂, D₃, D₄.","x̿: average the subgroup means; R̄: average the ranges."]},sources:[c("5.2.3"),r("book-501-600",538,"Centre line and control limit calculations; constants table")]},{id:"imr",name:"I-MR Chart Limits",short:"x̄ ± 2.66 MR̄ for individuals; 3.267 MR̄ for moving ranges.",group:"control",phase:5,syllabusRef:"5.2.2",supplementary:!1,definition:"When data arrive one at a time (daily KPI, weekly incident count), plot individuals with moving ranges of 2 consecutive points. σ_within = MR̄/1.128, so the limits are x̄ ± 3σ = x̄ ± **2.66** MR̄; the MR chart UCL is D₄MR̄ = **3.267** MR̄.",tex:String.raw`\text{UCL}_I = ${n(String.raw`\bar{x}`)} + 2.66\,${n(String.raw`\overline{MR}`)},\quad \text{LCL}_I = \bar{x} - 2.66\,\overline{MR}`,altTex:[{label:"MR chart",tex:String.raw`\text{UCL}_{MR} = 3.267\,\overline{MR},\quad \text{LCL}_{MR} = 0`}],variables:[{symbol:String.raw`\bar{x}`,meaning:"Mean of the individual values",unit:"data units"},{symbol:String.raw`\overline{MR}`,meaning:"Average moving range |xᵢ − xᵢ₋₁| (n − 1 of them)",unit:"data units"}],whenToUse:["One value per period — no natural subgroups.","Slow or expensive data (monthly billing accuracy).","Check normality: the I chart is sensitive to skew."],units:"Same units as the data.",example:{title:"Daily P1 incidents",scenario:"Five days: **10, 12, 11, 14, 13** incidents.",values:[{symbol:String.raw`\bar{x}`,value:"12",meaning:"mean"},{symbol:String.raw`\overline{MR}`,value:e(S.mr.cl,2),meaning:"mean of 2, 1, 3, 1"}],substituted:String.raw`\text{UCL} = 12 + 2.66 \times 1.75`,steps:[{tex:String.raw`MR = 2, 1, 3, 1 \Rightarrow \overline{MR} = 1.75`,note:"n − 1 = 4 ranges."},{tex:String.raw`\text{UCL}_I = ${t(S.i.ucl,3)},\ \text{LCL}_I = ${t(S.i.lcl,3)}`,note:"Individuals."},{tex:String.raw`\text{UCL}_{MR} = ${t(S.mr.ucl,3)}`,note:"Moving ranges."}],result:S.i.ucl,answer:`I chart ${e(S.i.lcl,2)} – ${e(S.i.ucl,2)}; MR chart 0 – ${e(S.mr.ucl,2)}`},solution:["Moving ranges 2, 1, 3, 1 → MR̄ = 1.75 (divide by 4, not 5).",`UCL_I = 12 + 2.66 × 1.75 = **${e(S.i.ucl,3)}**.`,`UCL_MR = 3.267 × 1.75 = ${e(S.mr.ucl,3)}.`],trap:{title:"2.66 vs 3.267 vs 3",body:'2.66 (= 3/1.128) is for the Individuals chart; 3.267 (= D₄ for n = 2) is for the MR chart. "x̄ ± 3MR̄" and "x̄ ± 3s" are both wrong.'},incorrect:{calculation:String.raw`12 + 3 \times 1.75 = 17.25`,result:"17.25",whyWrong:"MR̄ is not σ. Convert with ÷1.128 → 3/1.128 = 2.66.",correct:String.raw`12 + 2.66 \times 1.75 = ${t(S.i.ucl,3)}`,correctResult:e(S.i.ucl,3)},denominatorErrors:["Averaging moving ranges over n instead of n − 1.","Overall SD instead of MR̄/1.128.","Swapping the 2.66 and 3.267 constants."],related:["xbarR","cp","cpk"],examTools:{tables:[ye+" — d₂ = 1.128, D₄ = 3.267 for n = 2"],keys:["Write the |differences| column; there is one fewer than the data.","2.66 × MR̄ → M+, then x̄ ± MR."]},sources:[c("5.2.2"),r("book-501-600",538,"Individuals and MR chart centre lines and limits"),r("book-501-600",518,"Choosing an I-MR chart")]},{id:"pchart",name:"p Chart Limits",short:"Proportion defective: p̄ ± 3√[p̄(1 − p̄)/n].",group:"control",phase:5,syllabusRef:"5.2.5",supplementary:!1,definition:"A p chart plots the **proportion defective** in each subgroup — subgroup sizes may vary, and then each point gets its own limits. p̄ = total defectives ÷ total inspected. A negative LCL is set to 0.",tex:String.raw`\text{UCL}_p = ${n(String.raw`\bar{p}`)} + 3\sqrt{\dfrac{${n(String.raw`\bar{p}`)}(1 - \bar{p})}{${n("n_i")}}}`,variables:[{symbol:String.raw`\bar{p}`,meaning:"Overall proportion defective (Σd ÷ Σn)",unit:"fraction"},{symbol:"n_i",meaning:"Size of subgroup i",unit:"count"}],whenToUse:["Defectives (pass/fail units), constant or varying n.","For a count of defectives with constant n, an np chart is equivalent.","Defects (several per unit) → u or c chart instead."],units:"Fraction or percentage.",example:{title:"Provisioning errors",scenario:"Four daily samples of **100 orders** had **4, 6, 5, 5** defective orders.",values:[{symbol:String.raw`\bar{p}`,value:"0.05",meaning:"20/400"},{symbol:"n_i",value:"100",meaning:"orders"}],substituted:String.raw`0.05 + 3\sqrt{\dfrac{0.05 \times 0.95}{100}}`,steps:[{tex:String.raw`\sqrt{0.000475} = ${t(Math.sqrt(475e-6),5)}`,note:"σ_p."},{tex:String.raw`\text{UCL} = ${t(Q.points[0].ucl,4)}`,note:"+3σ."},{tex:String.raw`\text{LCL} = \max(0,\ ${t(.05-3*Math.sqrt(475e-6),4)}) = 0`,note:"Negative → 0."}],result:Q.points[0].ucl*100,answer:`UCL = ${e(Q.points[0].ucl*100,2)}%, centre ${e(Q.pbar*100,0)}%, LCL = 0`},solution:["p̄ = 20/400 = 0.05.",`σ_p = √(0.05 × 0.95/100) = ${e(Math.sqrt(475e-6),5)}.`,`UCL = **${e(Q.points[0].ucl*100,2)}%**; LCL = 0.`],trap:{title:"p vs np vs u",body:"p = proportion of defective UNITS; np = NUMBER of defective units (constant n); u = defects PER UNIT. With unequal n, never average the subgroup proportions — pool the totals."},incorrect:{calculation:String.raw`0.05 + 3 \times \dfrac{0.05 \times 0.95}{100}`,result:e((.05+3*475e-6)*100,2)+"%",whyWrong:"Forgot the square root.",correct:String.raw`0.05 + 3\sqrt{0.000475}`,correctResult:e(Q.points[0].ucl*100,2)+"%"},denominatorErrors:["Averaging subgroup proportions with unequal n.","Using the average n for a small subgroup.","Forgetting the root."],related:["npchart","uchart","prop1"],examTools:{tables:["No statistical table — 3σ limits"],keys:["p̄ × (1 − p̄) ÷ n, √, × 3 → M+; then p̄ ± MR.","Clamp a negative LCL to 0."]},sources:[c("5.2.5"),r("book-501-600",539,"p chart centre line and limits"),r("book-501-600",520,"Choosing attribute charts")]},{id:"npchart",name:"np Chart Limits",short:"Number defective (constant n): np̄ ± 3√[np̄(1 − p̄)].",group:"control",phase:5,syllabusRef:"5.2.6",supplementary:!1,definition:"An np chart plots the **count of defective units** per subgroup when every subgroup has the **same size n**. Centre line np̄ = total defectives ÷ number of subgroups. Its limits are exactly n times the p-chart limits.",tex:String.raw`\text{UCL}_{np} = ${n(String.raw`n\bar{p}`)} + 3\sqrt{${n(String.raw`n\bar{p}`)}(1 - ${n(String.raw`\bar{p}`)})}`,variables:[{symbol:String.raw`n\bar{p}`,meaning:"Average number defective per subgroup",unit:"count"},{symbol:String.raw`\bar{p}`,meaning:"Average proportion defective",unit:"fraction"}],whenToUse:["Pass/fail data, constant subgroup size.","Front-line teams find counts easier to read than percentages.","Varying n → use a p chart."],units:"Count of defective units.",example:{title:"Daily order audit",scenario:"Same audits: **n = 100** orders per day, defectives **4, 6, 5, 5**.",values:[{symbol:String.raw`n\bar{p}`,value:"5",meaning:"20 ÷ 4 days"},{symbol:String.raw`\bar{p}`,value:"0.05",meaning:""}],substituted:String.raw`5 + 3\sqrt{5 \times 0.95}`,steps:[{tex:String.raw`\sqrt{4.75} = ${t(Math.sqrt(4.75),4)}`,note:"σ_np."},{tex:String.raw`\text{UCL} = ${t(X.limits.ucl,3)},\ \text{LCL} = 0`,note:"Limits."}],result:X.limits.ucl,answer:`np chart: CL 5, UCL ${e(X.limits.ucl,2)}, LCL 0`},solution:["np̄ = 20 ÷ 4 = 5 defective orders per day.",`σ = √(5 × 0.95) = ${e(Math.sqrt(4.75),4)}.`,`UCL = **${e(X.limits.ucl,2)}** (= 100 × p-chart UCL).`],trap:{title:"Do not forget (1 − p̄)",body:"np̄ + 3√(np̄) is the c-chart formula (Poisson defects). Defectives are binomial, so the variance is np̄(1 − p̄)."},incorrect:{calculation:String.raw`5 + 3\sqrt{5} = ${t(5+3*Math.sqrt(5),3)}`,result:e(5+3*Math.sqrt(5),3),whyWrong:"c-chart formula — ignores (1 − p̄).",correct:String.raw`5 + 3\sqrt{4.75} = ${t(X.limits.ucl,3)}`,correctResult:e(X.limits.ucl,3)},denominatorErrors:["Giving p̄ (a fraction) as the centre line.","Dividing by total inspected instead of number of subgroups.","Using an np chart when n varies."],related:["pchart","uchart"],examTools:{tables:["No statistical table — 3σ limits"],keys:["np̄ × (1 − p̄), √, × 3, then np̄ ± that."]},sources:[c("5.2.6"),r("book-501-600",540,"nP chart centre line and limits")]},{id:"uchart",name:"u Chart Limits",short:"Defects per unit: ū ± 3√(ū/nᵢ).",group:"control",phase:5,syllabusRef:"5.2.4",supplementary:!1,definition:"A u chart plots **defects per unit** when the area of opportunity (units inspected) varies. ū = total defects ÷ total units; each subgroup gets limits ū ± 3√(ū/nᵢ). With a constant area of opportunity, a c chart (c̄ ± 3√c̄) plots the counts directly.",tex:String.raw`\text{UCL}_u = ${n(String.raw`\bar{u}`)} + 3\sqrt{\dfrac{${n(String.raw`\bar{u}`)}}{${n("n_i")}}}`,altTex:[{label:"c chart (constant opportunity)",tex:String.raw`\bar{c} \pm 3\sqrt{\bar{c}}`}],variables:[{symbol:String.raw`\bar{u}`,meaning:"Average defects per unit (Σc ÷ Σn)",unit:"defects/unit"},{symbol:"n_i",meaning:"Units in subgroup i",unit:"count"}],whenToUse:["Counting defects (several per unit possible).","Varying number of units per period.","Poisson assumption: defects are independent, rare events."],units:"Defects per unit.",example:{title:"Router configuration defects",scenario:"Batches of **4, 4, 2** routers had **12, 8, 10** configuration defects.",values:[{symbol:String.raw`\bar{u}`,value:"3",meaning:"30 ÷ 10"},{symbol:"n_i",value:"4",meaning:"batch 1"}],substituted:String.raw`3 + 3\sqrt{3/4}`,steps:[{tex:String.raw`\sqrt{0.75} = ${t(Math.sqrt(.75),4)}`,note:"σ_u for n = 4."},{tex:String.raw`\text{UCL}_1 = ${t(_.points[0].ucl,3)}`,note:"Batch 1."},{tex:String.raw`\text{UCL}_3 = ${t(_.points[2].ucl,3)}`,note:"Batch 3 (n = 2) is wider."}],result:_.points[0].ucl,answer:`ū = 3; batch-1 limits ${e(_.points[0].lcl,2)} – ${e(_.points[0].ucl,2)}`},solution:["ū = 30 ÷ 10 = 3 defects per router.",`n = 4: UCL = 3 + 3√0.75 = **${e(_.points[0].ucl,3)}**, LCL = ${e(_.points[0].lcl,3)}.`,`n = 2: UCL = ${e(_.points[2].ucl,3)}, LCL = 0.`],trap:{title:"Defects vs defectives",body:"u and c charts count DEFECTS (Poisson); p and np charts count DEFECTIVE units (binomial). A unit with three configuration errors is one defective but three defects."},incorrect:{calculation:String.raw`3 + 3\sqrt{3} = ${t(3+3*Math.sqrt(3),3)}`,result:e(3+3*Math.sqrt(3),3),whyWrong:"c-chart formula — ignores that each point is a rate over nᵢ units.",correct:String.raw`3 + 3\sqrt{3/4} = ${t(_.points[0].ucl,3)}`,correctResult:e(_.points[0].ucl,3)},denominatorErrors:["Averaging batch rates instead of pooling totals.","Dividing defects by number of batches (that is c̄).","Ignoring nᵢ inside the root."],related:["pchart","npchart","dpu"],examTools:{tables:["No statistical table — 3σ limits"],keys:["ū ÷ nᵢ, √, × 3 → M+; then ū ± MR.","Clamp a negative LCL to 0."]},sources:[c("5.2.4"),r("book-501-600",540,"Attribute chart formulas (u chart)"),r("book-501-600",520,"Choosing attribute charts")]},{id:"cbr",name:"Cost-Benefit Ratio",short:"Benefits ÷ costs (> 1 means worth doing); NPV discounts future cash.",group:"control",phase:5,syllabusRef:"5.3.1",supplementary:!1,definition:"Cost-benefit analysis decides which improvements to implement and sustain. The **benefit-cost ratio** divides total benefits by total costs; above 1, benefits exceed costs. When cash flows span years, compare **present values** — the NPV part is supplementary finance knowledge, not a syllabus formula.",tex:String.raw`\text{BCR} = \dfrac{${n(String.raw`\text{PV(benefits)}`)}}{${n(String.raw`\text{PV(costs)}`)}}`,altTex:[{label:"NPV (supplementary)",tex:String.raw`\text{NPV} = \sum_{t=0}^{T} \dfrac{CF_t}{(1 + r)^t}`}],variables:[{symbol:String.raw`\text{PV(benefits)}`,meaning:"Present value of savings / gains",unit:"currency"},{symbol:String.raw`\text{PV(costs)}`,meaning:"Present value of costs",unit:"currency"}],whenToUse:["Choosing between improvement options (Control 5.3.1).","Sign-off of the control plan and business case.","Use discounting when benefits arrive over several years."],units:"BCR is a unit-free ratio; NPV is in currency.",example:{title:"Ticket-routing automation",scenario:"Benefits worth **OMR 150,000** for costs of **OMR 100,000** (present values). Alternatively: invest 100,000 now for 45,000 a year for 3 years at 8%.",values:[{symbol:String.raw`\text{PV(benefits)}`,value:"150,000",meaning:"OMR"},{symbol:String.raw`\text{PV(costs)}`,value:"100,000",meaning:"OMR"}],substituted:String.raw`\text{BCR} = \dfrac{150{,}000}{100{,}000}`,steps:[{tex:String.raw`\text{BCR} = ${t(xe,2)}`,note:"Ratio."},{tex:String.raw`\text{NPV} = -100{,}000 + \textstyle\sum_{t=1}^{3} 45{,}000/1.08^t = ${t(be,0)}`,note:"Supplementary NPV."}],result:xe,answer:`BCR = ${e(xe,2)}; NPV of the 3-year option = OMR ${e(be,0)}`},solution:["BCR = 150,000 ÷ 100,000 = **1.50** → benefits exceed costs.",`NPV (supplementary): discount each 45,000 by 1.08ᵗ → OMR ${e(be,0)} > 0.`],trap:{title:"BCR vs ROI",body:"BCR uses gross benefits (1.5 here). ROI uses the net gain ÷ cost (50%). And never discount the year-0 investment."},incorrect:{calculation:String.raw`\dfrac{150{,}000 - 100{,}000}{100{,}000} = 0.5`,result:"0.50",whyWrong:"That is ROI as a fraction, not the benefit-cost ratio.",correct:String.raw`\dfrac{150{,}000}{100{,}000} = 1.5`,correctResult:"1.50"},denominatorErrors:["Inverting (costs ÷ benefits).","Mixing undiscounted future benefits with present costs.","Discounting the year-0 cost."],related:["roi","payback","copq"],extras:[{title:"Supplementary: net present value",body:`NPV is not written as a formula in the Green Belt syllabus. It is shown because multi-year benefits must be discounted before comparing them with today's cost. Example: −100,000 + 45,000/1.08 + 45,000/1.08² + 45,000/1.08³ = **OMR ${e(be,0)}**.`}],examTools:{tables:["No statistical table"],keys:["BCR: benefits ÷ costs.","NPV: for each year, CF ÷ (1 + r)^t with the xʸ key; accumulate with M+."]},sources:[c("5.3.1"),r("book-501-600",557,"Selecting solutions: impact, cost and time of each improvement")]}],o=i=>String.raw`\htmlClass{fm-var}{${i}}`,f=i=>({doc:"syllabus",pages:"p. 7",pdfPage:7,note:`Define topic ${i} — listed in the official syllabus`}),V=pt(84,600),J=pe(84,600,7),I=gt(45,2500,6),Ue=Ie(I),E=wt(680,800),ee=vt(770,800),F=[.95,.9,.98,.92],q=me(F),ke=F.reduce((i,l)=>i+l,0)/F.length,C=_e(420,105),ue=ht(22e3,38e3),Re=St(6e3,9e3,22e3,38e3),ze=[{label:"Wrong information given",value:45},{label:"System timeout",value:30},{label:"Unresolved fault",value:120},{label:"Transferred incorrectly",value:25},{label:"Callback missed",value:80}],$=ft(ze),te=bt(6.4,4),ae=Fe(6e4,4e4),Te=Fe(7e4,4e4),ne=Ce(4e4,6e4/12),ie=De(420*60,420),re=yt(180,45),p=(i,l=1)=>`${a(i*100,l)}%`,Ot=[{sigma:1,dpmo:"691,462.5"},{sigma:2,dpmo:"308,537.5"},{sigma:3,dpmo:"66,807.2"},{sigma:4,dpmo:"6,209.7"},{sigma:5,dpmo:"232.7"},{sigma:6,dpmo:"3.4"}],Pe=`| Quantity | What it counts | Example (600 tickets audited) |
|---|---|---|
| **Total units** | Every item produced or processed — good or bad | 600 tickets |
| **Defective units** | Units with *at least one* defect (a unit is either defective or not) | 60 tickets |
| **Total defects** | Every individual nonconformance; one unit can hold several | 84 defects |
| **Opportunities per unit** | Characteristics checked on each unit that could each be wrong | 7 fields |
| **Total opportunities** | Units × opportunities per unit | 600 × 7 = 4,200 |`,Lt=[{id:"dpu",name:"Defects per Unit (DPU)",short:"Average number of defects carried by each unit.",group:"core",phase:1,syllabusRef:"1.2.5",supplementary:!1,definition:"DPU is the **total number of defects** found divided by the **total number of units** inspected. It tells you how many defects an average unit carries. Because one unit can contain several defects, DPU can be greater than 1.",tex:String.raw`\text{DPU} = \dfrac{${o(String.raw`\text{Total defects}`)}}{${o(String.raw`\text{Total units}`)}} = \dfrac{${o("D")}}{${o("U")}}`,variables:[{symbol:"D",meaning:"Total defects — every individual nonconformance found, counting several per unit where they occur",unit:"defects (count)"},{symbol:"U",meaning:"Total units inspected or processed — good and bad",unit:"units (count)"}],whenToUse:["You want a simple defect rate per item and the number of opportunities is unknown or not meaningful.","Comparing the same product or service over time, where the opportunity count does not change.","As a building block for process-level metrics (total DPU across steps) and on Level 3 process maps."],units:"Defects per unit — a plain ratio, **not a percentage**. 0.14 means 14 defects per 100 units on average. Do not multiply by 100 or by 1,000,000.",example:{title:"Incident-ticket quality audit",scenario:"The service desk closed **600 incident tickets** last week. Quality assurance reviewed all of them and logged **84 defects** (wrong category, missing closure notes and so on). **60 tickets** had at least one defect.",values:[{symbol:"D",value:"84",meaning:"defects"},{symbol:"U",value:"600",meaning:"tickets"}],substituted:String.raw`\text{DPU} = \dfrac{84}{600}`,steps:[{tex:String.raw`D = 84 \quad (\text{not the 60 defective tickets})`,note:"Count defects, not defective units."},{tex:String.raw`U = 600 \quad (\text{all tickets reviewed})`,note:"The denominator is every unit, good or bad."},{tex:String.raw`\text{DPU} = \dfrac{84}{600} = ${a(V,2)}`,note:"Divide."}],result:V,answer:`DPU = ${a(V,2)} defects per ticket`},solution:["Identify **total defects** (84) — ignore the defective-unit count (60) for DPU.","Identify **total units** (600) — include the tickets that had no defects.",`DPU = 84 ÷ 600 = **${a(V,2)}**: on average each ticket carries ${a(V,2)} defects.`],trap:{title:"Defects vs defective units",body:"Exam stems often give **both** numbers: “60 tickets were defective, containing 84 defects”. DPU always uses **defects** (84). The proportion of defective units (60 ÷ 600 = 0.10) is a different metric."},incorrect:{calculation:String.raw`\text{DPU} = \dfrac{60}{600} = 0.10`,result:"0.10",whyWrong:"60 is the number of defective tickets. Several tickets held more than one defect, so this undercounts. DPU counts every defect.",correct:String.raw`\text{DPU} = \dfrac{84}{600} = ${a(V,2)}`,correctResult:a(V,2)},denominatorErrors:["Dividing by defective units instead of all units inspected.","Multiplying units by the number of process steps — every unit is still one unit.","Averaging DPUs from groups of different sizes instead of pooling defects and units."],related:["dpo","dpmo","fty","rty"],extras:[{title:"Five counts you must keep apart",body:Pe},{title:"Process DPU across several steps",body:"When every unit visits every step, the process DPU is the **sum** of the step DPUs (= all defects ÷ units). It is not their average."}],sources:[f("1.2.5"),{doc:"book-201-300",pages:"p. 225",pdfPage:28,note:"Worked DPU example: 2,666 defects ÷ 20,000 units = 0.1333"},{doc:"book-501-600",pages:"p. 585",pdfPage:88,note:"Glossary: DPU — total defects divided by total units"}]},{id:"dpo",name:"Defects per Opportunity (DPO)",short:"Defects as a share of every chance to be wrong.",group:"core",phase:1,syllabusRef:"1.2.5",supplementary:!1,supplementaryNote:"DPO is supporting background: the syllabus lists DPU and DPMO, and DPO is the step between them.",definition:"DPO is the **total number of defects** divided by the **total number of opportunities** for a defect. An *opportunity* is a characteristic of a unit that is checked and can be judged right or wrong. DPO lets you compare simple and complex units fairly.",tex:String.raw`\text{DPO} = \dfrac{${o("D")}}{${o("U")} \times ${o("O")}}`,variables:[{symbol:"D",meaning:"Total defects",unit:"defects"},{symbol:"U",meaning:"Total units",unit:"units"},{symbol:"O",meaning:"Opportunities per unit — characteristics checked on each unit",unit:"opportunities per unit"}],whenToUse:["Comparing processes or products that have different complexity (different numbers of opportunities).","As the intermediate step before DPMO."],units:"Defects per opportunity — a small decimal such as 0.02. Multiply by 1,000,000 to get DPMO, or by 100 to read it as a percentage of opportunities.",example:{title:"Ticket fields as opportunities",scenario:"Each incident ticket is checked on **7 fields** (category, priority, assignment group, configuration item, resolution code, closure notes, SLA timestamps). **600 tickets** were reviewed and **84 defects** found.",values:[{symbol:"D",value:"84",meaning:"defects"},{symbol:"U",value:"600",meaning:"tickets"},{symbol:"O",value:"7",meaning:"fields per ticket"}],substituted:String.raw`\text{DPO} = \dfrac{84}{600 \times 7}`,steps:[{tex:String.raw`U \times O = 600 \times 7 = 4{,}200`,note:"Total opportunities."},{tex:String.raw`\text{DPO} = \dfrac{84}{4{,}200} = ${a(J,4)}`,note:"Defects ÷ opportunities."}],result:J,answer:`DPO = ${a(J,4)}`},solution:["Count opportunities per unit: 7 checked fields.","Total opportunities = 600 × 7 = 4,200.",`DPO = 84 ÷ 4,200 = **${a(J,4)}**.`],trap:{title:"Counting opportunities",body:"Only characteristics that are actually **checked and can fail** count. A free-text comment box that nobody scores is not an opportunity. Inflating opportunities makes the process look better than it is."},incorrect:{calculation:String.raw`\text{DPO} = \dfrac{84}{600} = 0.14`,result:"0.14",whyWrong:"That is DPU. The opportunities per unit were left out of the denominator.",correct:String.raw`\text{DPO} = \dfrac{84}{600 \times 7} = ${a(J,4)}`,correctResult:a(J,4)},denominatorErrors:["Dividing by units only (gives DPU).","Dividing by opportunities per unit only, forgetting to multiply by the number of units.","Using an average opportunity count when unit types with different opportunities have different volumes — add units × opportunities type by type."],related:["dpu","dpmo"],extras:[{title:"Five counts you must keep apart",body:Pe}],sources:[f("1.2.5"),{doc:"book-501-600",pages:"p. 587",pdfPage:90,note:"Glossary: opportunities — characteristics that can be classified acceptable or unacceptable"}]},{id:"dpmo",name:"Defects per Million Opportunities (DPMO)",short:"Defects scaled to one million opportunities — the sigma-level currency.",group:"core",phase:1,syllabusRef:"1.2.5",supplementary:!1,definition:"DPMO is the total number of defects divided by the total number of opportunities, **expressed per million opportunities**. It is DPO × 1,000,000 and is the usual basis for quoting a process sigma level.",tex:String.raw`\text{DPMO} = \dfrac{${o("D")}}{${o("U")} \times ${o("O")}} \times 10^{6}`,altTex:[{label:"From DPO",tex:String.raw`\text{DPMO} = \text{DPO} \times 1{,}000{,}000`}],variables:[{symbol:"D",meaning:"Total defects",unit:"defects"},{symbol:"U",meaning:"Total units",unit:"units"},{symbol:"O",meaning:"Opportunities per unit",unit:"opportunities per unit"},{symbol:"10^6",meaning:"Scaling factor to “per million”",unit:"—"}],whenToUse:["Benchmarking processes of different complexity on one scale.","Converting performance to a sigma level (with the 1.5σ shift convention).","Reporting very low defect rates, where percentages become hard to read."],units:"Defects per million opportunities. 3,000 DPMO = 0.003 DPO = 0.3% of opportunities defective. DPMO is **not** the same as PPM defective units unless each unit has exactly one opportunity.",example:{title:"SIM activation orders",scenario:"The prepaid team processed **2,500 SIM activation orders**. Each order has **6 opportunities** for a defect. Audits found **45 defects**.",values:[{symbol:"D",value:"45",meaning:"defects"},{symbol:"U",value:"2,500",meaning:"orders"},{symbol:"O",value:"6",meaning:"opportunities per order"}],substituted:String.raw`\text{DPMO} = \dfrac{45}{2{,}500 \times 6} \times 10^{6}`,steps:[{tex:String.raw`U \times O = 2{,}500 \times 6 = 15{,}000`,note:"Total opportunities."},{tex:String.raw`\text{DPO} = \dfrac{45}{15{,}000} = ${a(pe(45,2500,6),4)}`,note:"Defects per opportunity."},{tex:String.raw`\text{DPMO} = ${a(pe(45,2500,6),4)} \times 1{,}000{,}000 = ${a(I,0)}`,note:"Scale to a million."}],result:I,answer:`DPMO = ${a(I,0)} (≈ ${a(Ue,1)}σ short-term)`},solution:["Total opportunities = 2,500 × 6 = 15,000.",`DPO = 45 ÷ 15,000 = ${a(pe(45,2500,6),4)}.`,`DPMO = ${a(pe(45,2500,6),4)} × 1,000,000 = **${a(I,0)}**.`,`Optional: with the conventional 1.5σ shift, ${a(I,0)} DPMO corresponds to about **${a(Ue,2)}σ** short-term (between the 4σ ≈ 6,210 and 5σ ≈ 233 rows of the table).`],trap:{title:"Three ways to lose the million",body:"The classic DPMO errors are: using **defective units** instead of defects; **forgetting the opportunities** (that gives defects per million *units*); and **forgetting × 1,000,000** (that leaves DPO). Each produces a plausible-looking number — check which one the options are built from."},incorrect:{calculation:String.raw`\dfrac{45}{2{,}500} \times 10^{6} = 18{,}000`,result:"18,000",whyWrong:"The opportunities per order were ignored, so this is defects per million orders, not per million opportunities. It overstates DPMO six-fold.",correct:String.raw`\dfrac{45}{2{,}500 \times 6} \times 10^{6} = ${a(I,0)}`,correctResult:a(I,0)},denominatorErrors:["Units instead of units × opportunities.","Defective units in the numerator instead of defects.","Averaging DPMO of shifts or sites of different sizes instead of pooling defects and opportunities.","For a multi-step process, using only one step’s opportunities while counting defects from every step."],related:["dpo","dpu","fty"],extras:[{title:"The visual pipeline",body:"Units → Opportunities (units × opportunities per unit) → Defects → Formula → Calculation → Result. The animation above walks this pipeline step by step."},{title:"DPMO ↔ sigma level (1.5σ shift convention)",body:`By convention, long-term DPMO is converted to a short-term sigma level by finding the Z value for the long-term defect rate and **adding 1.5** (the assumed long-term drift of the process mean). This is a convention, not a law of nature — it lets “6σ” be quoted as 3.4 DPMO.

| Short-term sigma level | Long-term DPMO |
|---|---|
${Ot.map(i=>`| ${i.sigma}σ | ${i.dpmo} |`).join(`
`)}

Values as tabulated in the training book, p.223.`},{title:"Five counts you must keep apart",body:Pe}],sources:[f("1.2.5"),{doc:"book-201-300",pages:"p. 223",pdfPage:26,note:"Sigma level vs DPMO table and the 1.5σ shift (attribute data treated as long-term)"},{doc:"book-501-600",pages:"p. 585",pdfPage:88,note:"Glossary: DPMO — total defects ÷ total opportunities, per million"},{doc:"book-501-600",pages:"p. 587",pdfPage:90,note:"Glossary: opportunities"}]},{id:"fty",name:"First Time Yield (FTY)",short:"Share of units that pass a step right first time — no rework, no scrap.",group:"core",phase:1,syllabusRef:"1.2.5",supplementary:!1,definition:"FTY (also called first-pass yield) is the number of units that complete a process step **correctly the first time, with no rework and no scrap**, divided by the number of units that **entered** that step. Reworked units are *not* first-pass successes, even though they end up good.",tex:String.raw`\text{FTY} = \dfrac{${o(String.raw`G_{1}`)}}{${o(String.raw`U_{\text{in}}`)}}`,altTex:[{label:"Final yield (for contrast)",tex:String.raw`\text{Final yield} = \dfrac{G_{1} + R_{\text{good}}}{U_{\text{in}}}`}],variables:[{symbol:"G_{1}",meaning:"Units good first time — passed with no rework and no scrap",unit:"units"},{symbol:String.raw`U_{\text{in}}`,meaning:"Units entering the step (or process)",unit:"units"},{symbol:String.raw`R_{\text{good}}`,meaning:"Units that were reworked and then passed (final yield only)",unit:"units"}],whenToUse:["Exposing the hidden factory: rework that final yield conceals.","Measuring each step before rolling them up into RTY."],units:"A proportion (0.85) or percentage (85%). Read the stem: if it asks for a percentage, multiply by 100.",example:{title:"Invoice data-capture step",scenario:"**800 supplier invoices** entered data capture. **680** were captured correctly first time, **90** were corrected and then passed, and **30** were rejected and returned to the supplier (scrapped from this process).",values:[{symbol:"G_{1}",value:"680",meaning:"right first time"},{symbol:String.raw`U_{\text{in}}`,value:"800",meaning:"invoices entering"}],substituted:String.raw`\text{FTY} = \dfrac{680}{800}`,steps:[{tex:String.raw`G_{1} = 680 \quad (\text{exclude the 90 reworked})`,note:"Only right-first-time units."},{tex:String.raw`\text{FTY} = \dfrac{680}{800} = ${a(E,2)} = ${p(E,0)}`,note:"Divide by units entering."},{tex:String.raw`\text{Final yield} = \dfrac{680 + 90}{800} = ${p(ee,2)}`,note:"Contrast: final yield hides rework."}],result:E*100,answer:`FTY = ${p(E,0)} (final yield ${p(ee,2)})`},solution:["First-pass good = 680 (the 90 corrected invoices do not count).","Units entering = 800 (include the 30 rejected).",`FTY = 680 ÷ 800 = **${p(E,0)}**.`,`Final yield = (680 + 90) ÷ 800 = ${p(ee,2)} — the ${a((ee-E)*100,2)}-point gap is the rework (hidden factory).`],trap:{title:"First pass vs final",body:"Phrases like **first pass**, **first time**, **without rework** or **right first time** mean reworked units count as failures. A report headline “yield 96%” is usually final yield."},incorrect:{calculation:String.raw`\dfrac{680 + 90}{800} = ${p(ee,2).replace("%",String.raw`\%`)}`,result:p(ee,2),whyWrong:"Adding the 90 reworked invoices gives final yield. First time yield excludes anything that needed rework.",correct:String.raw`\dfrac{680}{800} = ${p(E,0).replace("%",String.raw`\%`)}`,correctResult:p(E,0)},denominatorErrors:["Dividing by good output instead of units entering.","For a downstream step, using units that entered the whole process instead of units that entered *that step* (scrap upstream reduces the input).","Leaving scrapped units out of the denominator."],related:["rty","dpu"],sources:[f("1.2.5"),{doc:"book-101-200",pages:"pp. 115–116",pdfPage:18,note:"Level 3 process maps carry DPU, yield and RTY estimates (no FTY formula is given in the supplied pages)"}]},{id:"rty",name:"Rolled Throughput Yield (RTY)",short:"Probability a unit passes every step first time — multiply, never add.",group:"core",phase:1,syllabusRef:"1.2.5",supplementary:!1,definition:"RTY is the probability that a unit passes **all** process steps with zero defects, first time. It is the **product** of the first time yields of every step. Because losses compound, RTY is always less than or equal to the worst single step.",tex:String.raw`\text{RTY} = ${o(String.raw`\text{FTY}_{1}`)} \times ${o(String.raw`\text{FTY}_{2}`)} \times \cdots \times ${o(String.raw`\text{FTY}_{n}`)} = \prod_{i=1}^{n} \text{FTY}_{i}`,variables:[{symbol:String.raw`\text{FTY}_{i}`,meaning:"First time yield of step i, as a decimal",unit:"proportion"},{symbol:"n",meaning:"Number of steps in the process",unit:"steps"}],whenToUse:["Summarising the first-pass performance of a multi-step process or value stream.","Showing how many units need some rework somewhere (1 − RTY)."],units:"A proportion or percentage. Convert each step yield to a decimal before multiplying (95% → 0.95).",example:{title:"Broadband order-to-activation",scenario:`Four steps — order capture, credit check, line provisioning, activation test — have first time yields of **${F.map(i=>p(i,0)).join(", ")}**.`,values:F.map((i,l)=>({symbol:String.raw`\text{FTY}_{${l+1}}`,value:a(i,2),meaning:`step ${l+1}`})),substituted:String.raw`\text{RTY} = ${F.map(i=>a(i,2)).join(String.raw` \times `)}`,steps:[{tex:String.raw`0.95 \times 0.90 = ${a(me([.95,.9]),3)}`,note:"Multiply the first two."},{tex:String.raw`${a(me([.95,.9]),3)} \times 0.98 = ${a(me([.95,.9,.98]),4)}`,note:"Running product."},{tex:String.raw`${a(me([.95,.9,.98]),4)} \times 0.92 = ${a(q,4)} \approx ${p(q).replace("%",String.raw`\%`)}`,note:"Final RTY."}],result:q*100,answer:`RTY ≈ ${p(q)}`},solution:[`Convert to decimals: ${F.map(i=>a(i,2)).join(", ")}.`,`Multiply: ${F.map(i=>a(i,2)).join(" × ")} = ${a(q,4)}.`,`RTY = **${p(q)}** — only about ${a(q*100,0)} of every 100 orders flow through untouched.`],trap:{title:"Multiply — never add or average",body:`Averaging the yields gives ${p(ke,2)}, which describes a *typical step*, not the whole process. Subtracting the summed losses from 100% (100 − 5 − 10 − 2 − 8 = 75%) only approximates the product. Also use **first-pass** yields: multiplying final yields after rework hides the hidden factory.`},incorrect:{calculation:String.raw`\dfrac{0.95 + 0.90 + 0.98 + 0.92}{4} = ${a(ke,4)}`,result:p(ke,2),whyWrong:"An average treats the steps as alternatives. A unit must pass step 1 **and** step 2 **and** step 3 **and** step 4, so the probabilities multiply.",correct:String.raw`0.95 \times 0.90 \times 0.98 \times 0.92 = ${a(q,4)}`,correctResult:p(q)},denominatorErrors:["Computing one overall “last-step output ÷ first-step input” — that is a final-yield style ratio, not RTY.","Using step final yields (after rework) instead of first time yields.","Mixing percentages and decimals in the same product."],related:["fty","dpu","dpmo"],extras:[{title:"Book example (value stream map)",body:"The training book’s value-stream example multiplies five step yields: 0.92 × 0.94 × 0.59 × 0.96 × 0.96 = 0.47. Note how one weak step (0.59) drags the whole stream below 50%."}],sources:[f("1.2.5"),{doc:"book-101-200",pages:"p. 105",pdfPage:8,note:"Value stream map: RTY = .92 × .94 × .59 × .96 × .96 = .47"},{doc:"book-501-600",pages:"p. 588",pdfPage:91,note:"Glossary: RTY — probability of passing all steps with zero defects"}]},{id:"cycle",name:"Cycle Time",short:"Time per completed unit — net working time ÷ units completed.",group:"core",phase:1,syllabusRef:"1.2.5",supplementary:!1,definition:"Cycle time is the time it takes to complete one unit. For a period of work it is calculated as **available (net working) time divided by the number of units completed**. At a single step it is also the time taken to complete one unit or task at that step.",tex:String.raw`\text{Cycle time} = \dfrac{${o("T")}}{${o(String.raw`U_{c}`)}}`,variables:[{symbol:"T",meaning:"Net working time in the period (exclude breaks and downtime when the question says “working time”)",unit:"min, s or h"},{symbol:"U_{c}",meaning:"Units completed in that period (not units started)",unit:"units"}],whenToUse:["Measuring how fast a step or team actually produces output.","Comparing with takt time (customer pace) and lead time (customer wait) — see the supplementary comparisons."],units:"Time per unit. Convert hours to minutes (× 60) or minutes to seconds (× 60) **before** dividing, and answer in the unit the question asks for. Units per time (the inverse) is throughput.",example:{title:"L1 service desk agent",scenario:"An agent works an **8-hour shift** with **60 minutes** of breaks and resolves **105 tickets**.",values:[{symbol:"T",value:"420 min",meaning:"net working time"},{symbol:"U_{c}",value:"105",meaning:"tickets resolved"}],substituted:String.raw`\text{Cycle time} = \dfrac{420\ \text{min}}{105}`,steps:[{tex:String.raw`T = 8 \times 60 - 60 = 420\ \text{min}`,note:"Net working time."},{tex:String.raw`\dfrac{420}{105} = ${a(C,0)}\ \text{min per ticket}`,note:"Divide by units completed."},{tex:String.raw`${a(C,0)} \times 60 = ${a(C*60,0)}\ \text{s}`,note:"Convert if seconds are asked."}],result:C,answer:`${a(C,0)} minutes (${a(C*60,0)} s) per ticket`},solution:["Net working time = 8 × 60 − 60 = 420 min.",`Cycle time = 420 ÷ 105 = **${a(C,0)} min** per ticket (= ${a(C*60,0)} s).`],trap:{title:"Started vs completed — and the clock",body:"Divide by units **completed**; work still in progress is not output. And check the time basis: gross shift time or net working time, minutes or seconds."},incorrect:{calculation:String.raw`\dfrac{480}{105} = ${a(_e(480,105),2)}\ \text{min}`,result:`${a(_e(480,105),2)} min`,whyWrong:"The 60 minutes of breaks were counted as working time, so each ticket appears to take longer than it does.",correct:String.raw`\dfrac{420}{105} = ${a(C,0)}\ \text{min}`,correctResult:`${a(C,0)} min`},denominatorErrors:["Units started instead of units completed.","Averaging daily cycle times instead of pooling total time and total units.","Inverting the ratio (units ÷ time is throughput)."],related:["takt","lead"],extras:[{title:"Definitions vary",body:"The book glossary describes cycle time as the total elapsed time from when a task is started until it is completed. In calculations, the Define syllabus metric is usually computed as time ÷ units completed. Read each question’s wording carefully; elapsed customer wait across a whole process is closer to **lead time** (supplementary)."}],sources:[f("1.2.5"),{doc:"book-501-600",pages:"p. 585",pdfPage:88,note:"Glossary: cycle time"},{doc:"book-101-200",pages:"p. 105",pdfPage:8,note:"Value stream map shows step cycle times (C/T) in seconds"}]},{id:"copq",name:"Cost of Poor Quality (COPQ)",short:"The money lost because work was not right first time.",group:"quality",phase:1,syllabusRef:"1.2.3",supplementary:!1,definition:"COPQ is the cost of **not doing the right thing right the first time**: internal failure costs (found before the customer — rework, scrap, re-testing) plus external failure costs (found by or affecting the customer — penalties, warranty, complaints). Adding prevention and appraisal gives the total **cost of quality** (COQ).",tex:String.raw`\text{COPQ} = ${o(String.raw`C_{\text{IF}}`)} + ${o(String.raw`C_{\text{EF}}`)}`,altTex:[{label:"Total cost of quality",tex:String.raw`\text{COQ} = C_{\text{P}} + C_{\text{A}} + C_{\text{IF}} + C_{\text{EF}}`}],variables:[{symbol:String.raw`C_{\text{IF}}`,meaning:"Internal failure costs — rework, scrap, re-testing, write-offs found before delivery",unit:"currency per period"},{symbol:String.raw`C_{\text{EF}}`,meaning:"External failure costs — SLA credits, warranty, returns, complaint handling, lost customers",unit:"currency per period"},{symbol:String.raw`C_{\text{P}},\ C_{\text{A}}`,meaning:"Prevention (training, error-proofing) and appraisal (inspection, audits) — part of COQ",unit:"currency per period"}],whenToUse:["Estimating the size of the prize in a business case (Define: “Estimate COPQ”).","Prioritising problems by financial impact."],units:"Currency over a stated period. Put every cost on the **same period** (month, quarter, year) before adding.",example:{title:"Quarterly quality costs",scenario:"Training OMR 6,000 (prevention); ticket audits OMR 9,000 (appraisal); rework of failed provisioning orders OMR 18,000 and scrapped SIM cards OMR 4,000 (internal failure); SLA penalty credits OMR 31,000 and complaint handling OMR 7,000 (external failure).",values:[{symbol:String.raw`C_{\text{IF}}`,value:"22,000",meaning:"internal failure"},{symbol:String.raw`C_{\text{EF}}`,value:"38,000",meaning:"external failure"}],substituted:String.raw`\text{COPQ} = 22{,}000 + 38{,}000`,steps:[{tex:String.raw`C_{\text{IF}} = 18{,}000 + 4{,}000 = 22{,}000`,note:"Internal failures."},{tex:String.raw`C_{\text{EF}} = 31{,}000 + 7{,}000 = 38{,}000`,note:"External failures."},{tex:String.raw`\text{COPQ} = ${a(ue,0).replace(",","{,}")}\ \text{OMR}`,note:"Prevention and appraisal are excluded."}],result:ue,answer:`COPQ = OMR ${a(ue,0)} (COQ = OMR ${a(Re,0)})`},solution:["Classify each line into prevention, appraisal, internal or external failure.","Internal = 18,000 + 4,000 = 22,000. External = 31,000 + 7,000 = 38,000.",`COPQ = **OMR ${a(ue,0)}**. Total COQ including prevention and appraisal = OMR ${a(Re,0)}.`],trap:{title:"COPQ is not the whole cost of quality",body:"Options often include the grand total of all four categories. Under the failure-cost definition, prevention and appraisal are the costs of *good* quality. Some texts include appraisal in COPQ — always follow the definition the question gives."},incorrect:{calculation:String.raw`6{,}000 + 9{,}000 + 22{,}000 + 38{,}000 = 75{,}000`,result:`OMR ${a(Re,0)}`,whyWrong:"That is total cost of quality. Training and audits are investments to prevent or detect failure, not failure costs.",correct:String.raw`22{,}000 + 38{,}000 = 60{,}000`,correctResult:`OMR ${a(ue,0)}`},denominatorErrors:["Adding monthly and quarterly figures without converting to one period.","When asked for COPQ as a share of COQ, dividing by prevention + appraisal instead of the total."],related:["pareto","roi"],extras:[{title:"The hidden factory",body:"Much COPQ is invisible in accounts: re-keying data, chasing approvals, repeat calls. Estimating it in Define helps size the business case."}],sources:[f("1.2.3"),{doc:"book-501-600",pages:"p. 584",pdfPage:87,note:"Glossary: COPQ — cost of not doing the right thing right the first time"},{doc:"book-201-300",pages:"p. 230",pdfPage:33,note:"DMAIC roadmap lists “Estimate COPQ” as a Define step"}]},{id:"pareto",name:"Pareto Cumulative Percentage",short:"Sort descending, then accumulate to find the vital few.",group:"quality",phase:1,syllabusRef:"1.2.4",supplementary:!1,definition:"A Pareto chart sorts categories from **largest to smallest** and adds a cumulative-percentage line. The cumulative percentage after the k-th bar is the sum of the k largest values divided by the grand total. The few categories that reach roughly 80% are the “vital few” — though real data rarely splits exactly 80/20.",tex:String.raw`\text{Cum\%}_{k} = \dfrac{\sum_{i=1}^{k} ${o(String.raw`f_{(i)}`)}}{${o(String.raw`\sum f`)}} \times 100`,variables:[{symbol:String.raw`f_{(i)}`,meaning:"Value of the i-th category **after sorting descending** (count, cost, hours…)",unit:"count or currency"},{symbol:String.raw`\sum f`,meaning:"Grand total of all categories",unit:"same as f"},{symbol:"k",meaning:"Number of top categories included",unit:"—"}],whenToUse:["Choosing which defect types, causes or complaint reasons to attack first.","Comparing frequency vs impact (a cost-weighted Pareto may change the order)."],units:"Percent of the grand total. The y-axis on the left shows the counts; the right axis shows cumulative percentage from 0 to 100%.",example:{title:"Repeat calls by cause",scenario:`Repeat calls last month: ${ze.map(i=>`${i.label} ${i.value}`).join(", ")} (total 300). What cumulative percentage do the top 3 causes reach?`,values:$.slice(0,3).map((i,l)=>({symbol:String.raw`f_{(${l+1})}`,value:String(i.value),meaning:i.label})),substituted:String.raw`\text{Cum\%}_{3} = \dfrac{${$.slice(0,3).map(i=>i.value).join(" + ")}}{300} \times 100`,steps:[{tex:String.raw`\text{Sorted: } ${$.map(i=>i.value).join(String.raw`,\ `)}`,note:"Sort descending first."},{tex:String.raw`\text{Cum\%: } ${$.map(i=>a(i.cumPct,1)).join(String.raw`\% \to `)}\%`,note:"Running total ÷ 300."},{tex:String.raw`\text{Top 3} = \dfrac{245}{300} = ${a($[2].cumPct,1)}\%`,note:"Vital few."}],result:$[2].cumPct,answer:`${a($[2].cumPct,1)}% from the top 3 causes`},solution:["Sort descending: 120, 80, 45, 30, 25.","Running totals: 120, 200, 245, 275, 300.",`Cumulative %: ${$.map(i=>`${a(i.cumPct,1)}%`).join(" → ")}.`,`Top 3 reach **${a($[2].cumPct,1)}%**.`],trap:{title:"Sort before you accumulate",body:"Data in a stem is often listed in an arbitrary order. Accumulating in listed order gives the wrong categories. Also check whether the question asks for a single bar’s percentage or the **cumulative** percentage."},incorrect:{calculation:String.raw`\dfrac{45 + 30 + 120}{300} = 65\%`,result:"65%",whyWrong:"The first three categories as listed were used. The Pareto order is by size: 120, 80, 45.",correct:String.raw`\dfrac{120 + 80 + 45}{300} = ${a($[2].cumPct,1)}\%`,correctResult:`${a($[2].cumPct,1)}%`},denominatorErrors:["Dividing by the sum of only the categories shown in the question instead of the grand total.","Ranking by frequency when the question asks for cost impact (multiply frequency × cost per occurrence first)."],related:["copq"],sources:[f("1.2.4"),{doc:"book-501-600",pages:"p. 587",pdfPage:90,note:"Glossary: Pareto chart and Pareto principle"}]},{id:"improvement",name:"Percentage Improvement",short:"Change relative to the baseline — not percentage points.",group:"financial",phase:1,syllabusRef:"1.3.3",supplementary:!1,supplementaryNote:"Percentage improvement is named in the requirements for 1.3.2/1.3.3; the formula itself is standard arithmetic and is not printed in the supplied book pages.",definition:"Percentage improvement expresses the change in a metric **relative to its baseline**. For a lower-is-better metric (defects, MTTR, cost) it is (baseline − new) ÷ baseline × 100; for a higher-is-better metric (FCR, yield) it is (new − baseline) ÷ baseline × 100.",tex:String.raw`\text{Improvement} = \dfrac{${o("B")} - ${o("N")}}{${o("B")}} \times 100`,altTex:[{label:"Higher-is-better metric",tex:String.raw`\text{Improvement} = \dfrac{N - B}{B} \times 100`}],variables:[{symbol:"B",meaning:"Baseline value (before the project)",unit:"metric unit"},{symbol:"N",meaning:"New value (after the improvement)",unit:"same unit as B"}],whenToUse:["Stating project results and goals (e.g. “reduce MTTR by 40%”).","Comparing improvement across metrics with different units."],units:"Percent of baseline. When the metric is itself a percentage (e.g. breach rate 12% → 4.5%), the raw difference (7.5) is in **percentage points**; the relative improvement is 62.5%.",example:{title:"MTTR reduction",scenario:"Mean time to restore for P2 incidents fell from **6.4 hours** to **4.0 hours**.",values:[{symbol:"B",value:"6.4 h",meaning:"baseline"},{symbol:"N",value:"4.0 h",meaning:"new"}],substituted:String.raw`\dfrac{6.4 - 4.0}{6.4} \times 100`,steps:[{tex:String.raw`6.4 - 4.0 = 2.4\ \text{h}`,note:"Absolute change."},{tex:String.raw`\dfrac{2.4}{6.4} \times 100 = ${a(te,1)}\%`,note:"Relative to baseline."}],result:te,answer:`${a(te,1)}% improvement`},solution:["Change = 6.4 − 4.0 = 2.4 h.",`Improvement = 2.4 ÷ 6.4 × 100 = **${a(te,1)}%**.`],trap:{title:"Percentage points vs percent",body:"If a rate drops from 12% to 4.5%, it fell **7.5 percentage points** but improved by **62.5%**. Options often include both."},incorrect:{calculation:String.raw`\dfrac{6.4 - 4.0}{4.0} \times 100 = 60\%`,result:"60%",whyWrong:"The change was divided by the new value. Improvement is always relative to the baseline.",correct:String.raw`\dfrac{6.4 - 4.0}{6.4} \times 100 = ${a(te,1)}\%`,correctResult:`${a(te,1)}%`},denominatorErrors:["Dividing by the new value instead of the baseline.","Reporting the absolute difference (or percentage points) as a percentage improvement."],related:["roi","copq"],sources:[f("1.3.2"),f("1.3.3")]},{id:"roi",name:"Return on Investment (ROI)",short:"Net gain as a percentage of what was invested.",group:"financial",phase:1,syllabusRef:"1.3.3",supplementary:!0,supplementaryNote:"Supplementary: financial evaluation is in the 1.3.3 syllabus scope, but no ROI formula is given in the supplied sources. This is the common simple-ROI convention.",definition:"Simple ROI compares the **net gain** from a project with the investment: (benefit − investment) ÷ investment × 100. Use **net** benefit (savings minus any running costs) over a stated period, and keep benefit and cost on the same time basis.",tex:String.raw`\text{ROI} = \dfrac{${o(String.raw`B_{\text{net}}`)} - ${o("I")}}{${o("I")}} \times 100`,variables:[{symbol:String.raw`B_{\text{net}}`,meaning:"Net benefit in the period = gross savings − running costs",unit:"currency"},{symbol:"I",meaning:"Investment (one-off project cost)",unit:"currency"}],whenToUse:["Comparing candidate projects in a business case.","Reporting the financial result of a completed project (verified benefits)."],units:"Percent. Benefits and costs must cover the **same period** (e.g. first 12 months). A negative ROI means the investment has not been recovered in that period.",example:{title:"Automated ticket routing",scenario:"One-off cost **OMR 40,000**; gross savings **OMR 70,000 per year**; licence and support **OMR 10,000 per year**. First-year ROI?",values:[{symbol:String.raw`B_{\text{net}}`,value:"60,000",meaning:"net annual benefit"},{symbol:"I",value:"40,000",meaning:"investment"}],substituted:String.raw`\text{ROI} = \dfrac{60{,}000 - 40{,}000}{40{,}000} \times 100`,steps:[{tex:String.raw`B_{\text{net}} = 70{,}000 - 10{,}000 = 60{,}000`,note:"Gross → net."},{tex:String.raw`\dfrac{20{,}000}{40{,}000} \times 100 = ${a(ae,0)}\%`,note:"Net gain ÷ investment."}],result:ae,answer:`ROI = ${a(ae,0)}% in year one`},solution:["Net annual benefit = 70,000 − 10,000 = 60,000.",`ROI = (60,000 − 40,000) ÷ 40,000 × 100 = **${a(ae,0)}%**.`],trap:{title:"Gross vs net",body:`Using gross savings gives ${a(Te,0)}% and overstates the return. Also watch for monthly savings that must be annualised, and for “benefit ÷ cost” ratios dressed up as ROI.`},incorrect:{calculation:String.raw`\dfrac{70{,}000 - 40{,}000}{40{,}000} \times 100 = ${a(Te,0)}\%`,result:`${a(Te,0)}%`,whyWrong:"The OMR 10,000 annual running cost was ignored. ROI uses net benefit.",correct:String.raw`\dfrac{60{,}000 - 40{,}000}{40{,}000} \times 100 = ${a(ae,0)}\%`,correctResult:`${a(ae,0)}%`},denominatorErrors:["Dividing by the benefit instead of the investment.","Forgetting to subtract the investment (that is a benefit–cost ratio).","Mixing monthly benefits with an annual period."],related:["payback","improvement","copq"],sources:[f("1.3.3"),{doc:"book-201-300",pages:"p. 231",pdfPage:34,note:"Planning prompts: “Validate Financial Benefits”, project financial goal (target & time)"}]},{id:"payback",name:"Simple Payback Period",short:"How long until net savings repay the investment.",group:"financial",phase:1,syllabusRef:"1.3.3",supplementary:!0,supplementaryNote:"Supplementary: payback is in the 1.3.3 scope, but no formula is given in the supplied sources. This is the simple (undiscounted) convention.",definition:"Simple payback is the time needed for **net** savings to equal the investment: investment ÷ net benefit per period. The answer comes out in the same time unit as the benefit rate (per month → months).",tex:String.raw`\text{Payback} = \dfrac{${o("I")}}{${o(String.raw`B_{\text{net}}/\text{period}`)}}`,variables:[{symbol:"I",meaning:"Investment (one-off)",unit:"currency"},{symbol:String.raw`B_{\text{net}}/\text{period}`,meaning:"Net benefit per period (savings − running costs)",unit:"currency per month or year"}],whenToUse:["Quick screening of projects where cash recovery speed matters.","Explaining value to sponsors in plain terms."],units:"Time — months if the benefit is per month, years if per year. Convert explicitly when the question asks for a different unit (years × 12 = months).",example:{title:"Ticket routing (continued)",scenario:"Investment **OMR 40,000**; net benefit **OMR 60,000 per year**. Payback in months?",values:[{symbol:"I",value:"40,000",meaning:"investment"},{symbol:String.raw`B_{\text{net}}/\text{period}`,value:"5,000 / month",meaning:"60,000 ÷ 12"}],substituted:String.raw`\text{Payback} = \dfrac{40{,}000}{5{,}000}`,steps:[{tex:String.raw`60{,}000 \div 12 = 5{,}000\ \text{per month}`,note:"Match the time unit asked."},{tex:String.raw`\dfrac{40{,}000}{5{,}000} = ${a(ne,0)}\ \text{months}`,note:"Investment ÷ monthly net benefit."}],result:ne,answer:`${a(ne,0)} months`},solution:["Monthly net benefit = 60,000 ÷ 12 = 5,000.",`Payback = 40,000 ÷ 5,000 = **${a(ne,0)} months** (0.67 years).`],trap:{title:"Time units",body:"40,000 ÷ 60,000 = 0.67 is in **years**. Reporting “0.67 months” is a classic slip. Also deduct running costs: using gross savings shortens payback artificially."},incorrect:{calculation:String.raw`\dfrac{40{,}000}{70{,}000/12} = ${a(Ce(4e4,7e4/12),1)}\ \text{months}`,result:`${a(Ce(4e4,7e4/12),1)} months`,whyWrong:"Gross savings were used; the OMR 10,000 per year running cost reduces the net benefit.",correct:String.raw`\dfrac{40{,}000}{60{,}000/12} = ${a(ne,0)}\ \text{months}`,correctResult:`${a(ne,0)} months`},denominatorErrors:["Dividing by annual benefit and labelling the answer months.","Using gross instead of net benefit.","Inverting (benefit ÷ investment)."],related:["roi"],sources:[f("1.3.3")]},{id:"takt",name:"Takt Time",short:"The pace of customer demand — available time ÷ demand.",group:"supplementary",phase:1,syllabusRef:"1.2.5",supplementary:!0,supplementaryNote:"Supplementary comparison: takt time is not explicitly listed in the Define syllabus text. It is taught here to contrast with cycle time.",definition:"Takt time is the rate at which one unit must be completed to meet customer demand: **available working time ÷ customer demand** in that time. If cycle time is longer than takt time, the process cannot keep up.",tex:String.raw`\text{Takt time} = \dfrac{${o(String.raw`T_{\text{avail}}`)}}{${o("D")}}`,variables:[{symbol:String.raw`T_{\text{avail}}`,meaning:"Available working time (exclude planned breaks)",unit:"min or s"},{symbol:"D",meaning:"Customer demand in the same period",unit:"units"}],whenToUse:["Balancing a line or staffing a service desk to demand.","Comparing with cycle time to see whether capacity meets demand."],units:"Time per unit. Convert available time to the unit asked (usually seconds) before dividing.",example:{title:"Activation desk",scenario:"The desk runs an **8-hour** day with **60 minutes** of breaks; customers request **420 activations per day**.",values:[{symbol:String.raw`T_{\text{avail}}`,value:"25,200 s",meaning:"420 min × 60"},{symbol:"D",value:"420",meaning:"activations"}],substituted:String.raw`\text{Takt} = \dfrac{25{,}200\ \text{s}}{420}`,steps:[{tex:String.raw`(480 - 60) \times 60 = 25{,}200\ \text{s}`,note:"Available seconds."},{tex:String.raw`\dfrac{25{,}200}{420} = ${a(ie,0)}\ \text{s}`,note:"One activation every minute."}],result:ie,answer:`${a(ie,0)} s per activation`},solution:["Available time = (480 − 60) × 60 = 25,200 s.",`Takt = 25,200 ÷ 420 = **${a(ie,0)} s**.`],trap:{title:"Takt is demand-driven",body:"Takt time does not depend on how fast the team works — that is cycle time. Changing staffing changes cycle time, not takt."},incorrect:{calculation:String.raw`\dfrac{480 \times 60}{420} = ${a(De(28800,420),1)}\ \text{s}`,result:`${a(De(28800,420),1)} s`,whyWrong:"Planned breaks are not available working time.",correct:String.raw`\dfrac{420 \times 60}{420} = ${a(ie,0)}\ \text{s}`,correctResult:`${a(ie,0)} s`},denominatorErrors:["Demand for a different period than the available time (per day vs per shift).","Inverting (demand ÷ time)."],related:["cycle","lead"],sources:[f("1.2.5")]},{id:"lead",name:"Lead Time (Little's Law)",short:"How long a unit waits in the system — WIP ÷ throughput.",group:"supplementary",phase:1,syllabusRef:"1.2.5",supplementary:!0,supplementaryNote:"Supplementary comparison: lead time and Little's Law are not explicitly listed in the Define syllabus text. Taught here to contrast with cycle time.",definition:"Lead time is the total time a unit spends in the process from request to delivery, including waiting. For a stable process, Little's Law gives the average: **work in progress ÷ throughput**.",tex:String.raw`\text{Lead time} = \dfrac{${o(String.raw`\text{WIP}`)}}{${o(String.raw`\text{TH}`)}}`,variables:[{symbol:String.raw`\text{WIP}`,meaning:"Average number of units in the process (queue + in work)",unit:"units"},{symbol:String.raw`\text{TH}`,meaning:"Average throughput (completion rate)",unit:"units per day or hour"}],whenToUse:["Estimating customer waiting time from backlog and completion rate.","Showing that cutting WIP shortens lead time."],units:"Time — in the unit of the throughput rate (per day → days). Convert the rate first if the answer must be in another unit.",example:{title:"Fault-repair backlog",scenario:"About **180 open tickets** sit in the repair queue on average; the team closes **45 tickets per day**.",values:[{symbol:String.raw`\text{WIP}`,value:"180",meaning:"open tickets"},{symbol:String.raw`\text{TH}`,value:"45 / day",meaning:"closures"}],substituted:String.raw`\text{Lead time} = \dfrac{180}{45}`,steps:[{tex:String.raw`\dfrac{180}{45} = ${a(re,0)}\ \text{days}`,note:"WIP ÷ throughput."}],result:re,answer:`${a(re,0)} days`},solution:[`Lead time = 180 ÷ 45 = **${a(re,0)} days**.`,"Cycle time per ticket might be minutes — the difference is waiting."],trap:{title:"Cycle time ≠ lead time",body:"A ticket can take 20 minutes of work (cycle time) yet wait four days in a queue (lead time). Questions about customer waiting are lead-time questions."},incorrect:{calculation:String.raw`\dfrac{45}{180} = 0.25\ \text{days}`,result:"0.25 days",whyWrong:"The ratio is inverted. Little's Law divides WIP by throughput.",correct:String.raw`\dfrac{180}{45} = ${a(re,0)}\ \text{days}`,correctResult:`${a(re,0)} days`},denominatorErrors:["Throughput per hour with an answer required in days (convert using the working hours per day).","Inverting the ratio."],related:["cycle","takt"],sources:[f("1.2.5")]}],x=["No table needed"],Ut={dpu:{tables:x,keys:["defects ÷ units — a plain ratio, do not × 100."]},dpo:{tables:x,keys:["units × opportunities first (M+), then defects ÷ MR."]},dpmo:{tables:["Sigma ↔ DPMO conversion table (only if a sigma level is asked)"],keys:["defects ÷ (units × opportunities) × 1,000,000.","Keep all digits until the final step."]},fty:{tables:x,keys:["(units in − reworked − scrapped) ÷ units in × 100."]},rty:{tables:x,keys:["Multiply the step yields as decimals: 0.95 × 0.90 × … — never add or average."]},cycle:{tables:x,keys:["Convert hours to minutes (× 60) before dividing by units completed."]},copq:{tables:x,keys:["Add internal and external failure costs only (M+ each)."]},pareto:{tables:x,keys:["Sort descending on the notepad first; running total ÷ grand total × 100."]},improvement:{tables:x,keys:["(baseline − new) ÷ baseline × 100."]},roi:{tables:x,keys:["(net benefit − cost) ÷ cost × 100 over the same period."]},payback:{tables:x,keys:["investment ÷ net benefit per period."]},takt:{tables:x,keys:["(shift minutes − breaks) × 60 ÷ demand for seconds."]},lead:{tables:x,keys:["WIP ÷ throughput — check the time units match."]}},At=[...Lt.map(i=>({...i,examTools:i.examTools??Ut[i.id]})),...qt],It=Object.fromEntries(At.map(i=>[i.id,i])),Ft=[{id:1,name:"Define",blurb:"Defects, yields, cycle time, COPQ, Pareto and the business case.",accent:"indigo"},{id:2,name:"Measure",blurb:"FMEA, descriptive statistics, z-scores, Gage R&R and capability.",accent:"teal"},{id:3,name:"Analyze",blurb:"Standard error, intervals, sample size, t, ANOVA, χ² and proportion tests.",accent:"violet"},{id:4,name:"Improve",blurb:"Correlation, regression and R².",accent:"amber"},{id:5,name:"Control",blurb:"Xbar-R, I-MR, p, np and u chart limits; cost-benefit.",accent:"coral"}];export{At as F,Ft as a,It as f};
